(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-massv-multimodal-adaptation-and-self-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-1\">一 · 一个图文客服请求的端到端时间线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-2\">二 · 旧方案：文本域草稿模型的直接迁移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-3\">三 · 为什么非改不可：接受率是唯一杠杆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-4\">四 · 落差的机制：视觉条件如何改写草稿分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-5\">五 · 蒸馏目标的写法与验证回退的一致性代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-6\">六 · 部署侧的净收益判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-7\">七 · 请求形态：视觉 token 把输入长度变成双峰分布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-8\">八 · 并发与批大小：草稿模型与目标模型的批几何不一致</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-9\">九 · SLO：首 token 延迟与每 token 延迟必须分开承诺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-10\">十 · 负载塑造方案：分桶、回退与草稿档位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-11\">十一 · 方案反过来限制负载：KV 回退与一致性边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-12\">十二 · 负载形态如何反噬方案：从图文请求分布到投机收益的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-13\">十三 · 草稿侧轻量前向的算子选型与精度档位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-14\">十四 · tcgen05、TMEM 与 2-SM MMA 在草稿解码中的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-15\">十五 · 视觉条件的数值通路：从目标侧编码到草稿侧消费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-16\">十六 · 验证阶段的并行前向与累加误差的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-17\">十七 · 精度档位与接受率的联合调优</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-18\">十八 · 显存账本的三本账：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-19\">十九 · 视觉 token 是 KV 账本里的隐形放大器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-20\">二十 · 分页、压缩、复用、卸载：四种手段的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-21\">二十一 · 带宽瓶颈在哪：HBM 读放大与验证前向</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-22\">二十二 · 一个可复算的显存预算（示例口径）</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-23\">二十三 · 回退一致性与容量规划的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-24\">二十四 · 连续批处理下的草稿-验证耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-25\">二十五 · Chunked prefill 与视觉编码段的切分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-26\">二十六 · 优先级、抢占与 KV 回退的一致性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-27\">二十七 · 分离式预填/解码与草稿模型的落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-28\">二十八 · 尾延迟的压法：接受率方差与批内隔离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-29\">二十九 · 多模态投机解码的批调度边界：视觉条件如何改写连续批处理与抢占代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-30\">三十 · 从单卡草稿到多卡拓扑：切分维度决定通信形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-31\">三十一 · NVLink 5 与 NVSwitch：机柜内带宽的可用面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-32\">三十二 · All-Reduce 与 All-to-All 的代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-33\">三十三 · NIXL 传输：分离式部署的数据面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-34\">三十四 · 通信何时成为瓶颈：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-35\">三十五 · 草稿模型与目标模型分离部署时的通信边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-36\">三十六 · 精度塌陷：接受率掉下去时，先分清是分布问题还是数值问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-37\">三十七 · OOM：草稿模型省下的显存，会被视觉 token 与回退缓冲吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-38\">三十八 · 批抖动：接受前缀长度不一致，把批内同步拖成尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-39\">三十九 · 尾延迟：视觉编码段与解码段必须分开计量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-40\">四十 · 静默降级：输出仍“对”，但等价性与加速都已失守</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-41\">四十一 · 回滚：按失败模式分层，而不是整体回退到无投机解码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-42\">四十二 · 多模态投机解码的失效边界：从接受率塌陷到静默降级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-43\">四十三 · 口径先于数字：这份材料能读出什么、不能读出什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-44\">四十四 · 硬件档位：Blackwell 上哪些量随档位变、哪些不变</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-45\">四十五 · batch 与并发：为什么 MASSV 的收益在小 batch 下才成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-46\">四十六 · 指标口径：TTFT、TPOT、吞吐、显存、功耗各自测什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-47\">四十七 · 哪些提升不可比：四类典型误配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-48\">四十八 · 复现时的最小实测集：把缺失的数字补在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-49\">四十九 · 迁移到非 MASSV 目标模型时，草稿侧的三个耦合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-50\">五十 · 换领域时，蒸馏数据的覆盖度就是接受率的上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-51\">五十一 · 规模上限：视觉 token 增长如何吃掉投机收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-52\">五十二 · 不适用的场景：三类请求不该套这套方案</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-53\">五十三 · 迁移检查清单：把判断落到可测的量上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-massv-multimodal-adaptation-and-self-2025-sec-54\">五十四 · 迁移边界：草稿对齐在什么条件下失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:572px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 572.4 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入后由目标 VLM 的视觉编码器对图像做前向，得到视觉 toke…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">目标模型以图文上下文做一次前向，产出首个 token 及其 KV 状态…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">草稿模型在多模态自适应后消费视觉条件与已生成前缀，连续预测若干候选 t…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">目标模型对候选 token 序列做并行验证，逐位比较分布并接受最长一致…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">被拒绝位置由目标模型分布重新采样，KV cache 回退到接受前缀长度…</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"490.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">循环直至终止符或长度上限，输出与目标模型单独解码一致的序列。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-1\">一 · 一个图文客服请求的端到端时间线</h3>\n<p>设想一个在线图文客服：用户上传一张报错截图并附一句“这个怎么修”。请求进入推理栈后，目标 VLM 的视觉编码器先对图像做一次前向，得到视觉 token 并投影进语言模型嵌入空间；随后目标模型以图文上下文做一次前向，产出首 token 及其 KV 状态。从这里开始进入自回归解码：每吐一个 token，目标模型就要完整前向一次，而图像 token 始终占据上下文的一段固定前缀。工程上真正难受的地方在于，这段前缀不随解码推进而消失，它让每一步解码的注意力计算都背上了一份恒定的额外负担，同时首 token 延迟被视觉编码段单独拉长。</p>\n<p>把投机解码接进来是自然的想法：用一个轻量草稿模型连续猜若干 token，目标模型并行验证，接受前缀直接写入 KV cache。文本域里这套机制成熟且收益明确，但搬到图文请求上，接受率会掉。原因不在验证逻辑，而在草稿模型的输入条件——它只见过纯文本前缀，没见过图像 token 改写后的上下文分布。视觉 token 一旦插入，上下文的条件分布整体偏移，草稿模型给出的候选序列与目标分布的逐位一致概率下降，验证阶段接受的 prefix 变短，目标模型前向次数回升，端到端延迟的改善被吃掉。</p>\n<p>这条时间线上有三段代价需要分开计量：视觉编码段（一次性，但绝对延迟不低）、首 token 段（含目标模型首次前向）、解码段（每 token 一次目标前向）。投机解码只作用于第三段，而第三段的收益完全由接受率决定。这就是 MASSV 要处理的问题现场：不是验证机制不好，而是草稿模型与多模态分布之间存在落差。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-2\">二 · 旧方案：文本域草稿模型的直接迁移</h3>\n<p>论文之前的主流做法是把文本域投机解码的草稿模型原样搬到 VLM 上。草稿模型通常是目标语言模型的小号版本、或是同族小模型、或是经过蒸馏的独立小模型，其训练分布是纯文本语料。部署时它接收已生成的文本前缀，预测 k 个候选 token，目标模型对这 k 个位置做一次并行前向，逐位比较分布并接受最长一致前缀，被拒位置由目标分布重采样。</p>\n<p>这套流程在纯文本负载上成立，是因为草稿模型与目标模型共享同一个条件上下文——都是文本。但图文请求的条件上下文是 $(x_{&lt;t}, v)$，其中 $v$ 是视觉 token 序列。草稿模型若只消费 $x_{&lt;t}$，它实际在逼近 $p_{\\text{draft}}(x_t \\mid x_{&lt;t})$，而目标模型在逼近 $p_{\\text{target}}(x_t \\mid x_{&lt;t}, v)$。两者的差距不是训练不足，而是条件变量缺失：视觉 token 改变了上下文分布，草稿模型未见过图像条件，逐位比较时一致的概率被系统性压低。</p>\n<p>代价体现在三个维度。延迟上，接受前缀变短意味着每轮验证推进的 token 数减少，目标模型前向次数上升，每 token 延迟向无投机时的基线回退。吞吐上，验证轮次变密，目标模型的并行验证批次被切得更碎，批内有效 token 密度下降。显存上，草稿模型本身要占一份权重，而它带来的收益却在下降，等于用显存换了一个不成立的加速承诺。更隐蔽的是首 token 延迟不受益：视觉编码段和首次前向仍在关键路径上，投机解码对这段毫无帮助。</p>\n<p>一个具体例子：图像问答负载中，图像 token 数量随分辨率上升，上下文前缀变长。文本域草稿模型在长视觉前缀下预测的候选 token，往往在描述性位置上与目标分布分歧——目标模型在图像条件下倾向具体名词，草稿模型按文本先验倾向泛化措辞。验证逐位比较时，前几个 token 就被拒，接受前缀长度退化到接近零，投机解码退化为“猜了白猜”，还多付了一次草稿前向的开销。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-3\">三 · 为什么非改不可：接受率是唯一杠杆</h3>\n<p>投机解码的加速比结构决定了接受率是唯一杠杆。设每轮草稿预测 $k$ 个 token，平均接受前缀长度为 $\\alpha$（$0&lt;\\alpha\\le k$），目标模型每轮做一次并行前向。相对无投机的每 token 一次前向，目标模型前向次数的缩减比例近似为 $\\alpha$。端到端每 token 延迟可写成：</p>\n<div class=\"formula\">$$T_{\\text{token}} \\approx \\frac{T_{\\text{target forward}}}{\\alpha} + T_{\\text{draft forward}}$$</div>\n<p>草稿前向是轻量的，$T_{\\text{draft forward}}$ 远小于 $T_{\\text{target forward}}$，所以延迟主要由 $\\alpha$ 决定。$\\alpha$ 下降时，第一项线性上升，草稿开销变成纯负担。这就是“非改不可”的定量理由：文本域草稿模型在 VLM 上的 $\\alpha$ 被视觉条件拖低，而工程上无法通过调大 $k$ 来补偿——$k$ 增大只增加草稿前向与验证宽度，不改变逐位一致的概率。</p>\n<p>还有一层系统代价：视觉编码器只在目标模型侧运行一次，草稿模型复用其视觉表示，避免重复编码开销摊薄到每轮解码。但如果草稿模型根本不消费视觉表示，这份“复用”就是名义上的——视觉编码的成本仍然只由目标模型承担，而草稿模型没有从中获得任何条件信息。要让视觉编码开销真正被摊薄，草稿模型必须在视觉条件下预测，否则每轮解码都在为一份未被利用的视觉表示付费。</p>\n<p>工程判断因此清晰：不改目标模型权重的前提下，唯一可动的变量是草稿模型的条件输入与监督分布。目标模型冻结保证输出分布不变，验证阶段逐位比较与重采样保证等价性；草稿模型则需要在图像条件下逼近目标分布，而不是在文本条件下逼近文本分布。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-4\">四 · 落差的机制：视觉条件如何改写草稿分布</h3>\n<p>把落差拆成可操作的机制。目标模型在图文输入上的下一 token 分布是 $p_{\\text{target}}(x_t \\mid x_{&lt;t}, v)$，草稿模型的可训练部分是其条件路径。文本域草稿模型的结构里没有接收 $v$ 的入口，它的分布是 $p_{\\text{draft}}(x_t \\mid x_{&lt;t};\\theta)$。即便用目标模型在纯文本上的输出做蒸馏，$\\theta$ 收敛到的也是文本条件分布，视觉条件的信息从未进入监督信号。</p>\n<p>多模态自适应要做的就是给草稿模型开一个消费视觉条件的入口，使其分布变为 $p_{\\text{draft}}(x_t \\mid x_{&lt;t}, \\tilde{v};\\theta)$，其中 $\\tilde{v}$ 是目标模型已产生的压缩后视觉表示。这里的关键设计约束是：草稿模型不重复运行视觉编码器，它接收的是目标模型侧已经算好的视觉表示，因此自适应层只做条件注入，不引入第二份视觉编码开销。代价是草稿模型的上下文变长——视觉表示进入草稿上下文后，草稿前向的注意力计算量上升，视觉 token 数量增长会抬高这部分开销，抵消部分投机收益。</p>\n<p>监督侧的落差同样具体。仅做多模态自适应而不改监督分布，草稿模型有了视觉入口，但仍在文本语料上训练，视觉入口学不到与目标分布对齐的映射。仅做自数据蒸馏而不做自适应，草稿模型拿到的是目标模型在图文输入上的分布，但它无法消费视觉条件，监督信号与输入条件不匹配，接受率提升有限。两条手段分别作用于输入条件与监督分布，缺一都会削弱视觉条件下的对齐。</p>\n<p>一个具体机制例子：目标模型在图文样本上自采样，产出 $(x_{&lt;t}, v) \\to p_{\\text{target}}(\\cdot)$ 的监督对；草稿模型在自适应层注入 $\\tilde{v}$ 后，最小化其分布与目标分布在视觉条件下的差异。训练目标只作用于草稿模型，目标模型权重冻结，因此最终输出分布与目标模型单独解码一致——这是该方法在工程上可接受的前提：加速不以改变输出为代价。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-5\">五 · 蒸馏目标的写法与验证回退的一致性代价</h3>\n<p>论文给出的蒸馏目标写作：</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\text{distill}} = -\\sum_{t} \\log p_{\\text{target}}(x_t \\mid x_{&lt;t}, v) \\cdot \\mathbb{1}\\left[\\text{accept}(x_t)\\right]$$</div>\n<p>这个式子的工程含义比数学含义更重要：监督信号来自目标模型自身在图文输入上的分布，指示函数把训练重心放在会被接受的位置上。数据由目标模型自采样生成，覆盖图像问答与描述类负载，避免人工标注多模态草稿训练集。代价是蒸馏数据的覆盖度直接决定分布外图文请求的接受率——长尾负载未被采样覆盖时，草稿模型在这些请求上的 $\\alpha$ 下降，投机收益被抵消。这不是训练技巧能完全弥补的，属于数据配方的系统性局限。</p>\n<p>验证阶段的一致性代价落在 KV cache 的回退上。接受前缀写入 KV cache，被拒部分回退到接受长度，再由目标分布重采样。回退与重采样的正确性决定输出是否与目标模型单独解码等价。工程上容易出错的地方是：草稿模型预测了 $k$ 个位置，目标模型并行前向产出这 $k$ 个位置的目标分布，逐位比较接受最长一致前缀；被拒的第一个位置由目标分布重采样，其后位置全部丢弃。若回退长度与接受前缀长度不一致，或重采样用了草稿分布而非目标分布，等价性即被破坏。这条路径上没有任何近似空间，它是方法成立与否的硬约束。</p>\n<p>显存侧的代价需要单独算。草稿模型只做轻量前向，显存占用低于目标模型，可放在低精度档位以腾出 KV cache 空间。但草稿模型与目标模型可同卡或分离部署，取决于显存余量；同卡部署时草稿权重与 KV cache 争抢同一块显存，分离部署时多一跳通信。材料未给出并行拓扑，部署侧需按实际显存余量做取舍。监控指标应包括接受率、每轮接受前缀长度与目标模型前向次数——这三个量直接对应上面延迟公式里的 $\\alpha$ 与 $T_{\\text{target forward}}$ 计数。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-6\">六 · 部署侧的净收益判断</h3>\n<p>把收益判断落到可测的量上。净收益取决于接受率提升幅度能否覆盖三份新增成本：草稿模型前向、草稿模型显存占用、视觉表示进入草稿上下文后的注意力开销。视觉编码段与首 token 段不受投机解码影响，SLO 需要把这两段与解码段分开计量，否则平均延迟的改善会掩盖首 token 延迟的未变。批调度上，需按视觉 token 数量分桶以平衡草稿模型上下文长度——长视觉前缀的请求与短前缀请求混批，草稿前向的开销被长前缀请求主导，短请求的收益被稀释。</p>\n<p>对 Blackwell 部署而言，草稿模型放低精度档位、目标模型保持验证精度，是一条不改变目标模型权重的加速路径；目标模型负责验证保证输出一致，草稿模型负责把目标前向次数压下来。这条路径的成立条件不是硬件参数，而是接受率在真实负载分布上的表现：蒸馏数据覆盖度不足时，长尾图文请求的接受率下降会直接抵消收益；视觉 token 数量增大时，草稿上下文变长又会吃掉一部分节省。因此容量规划不能按论文主张的机制收益折算，必须按实际负载实测接受率与前向次数，再代入上面的延迟公式做容量反推。材料未给出接受率、加速比与硬件档位数字，任何按固定加速比做的容量承诺都缺乏依据。</p>\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-7\">七 · 请求形态：视觉 token 把输入长度变成双峰分布</h3>\n<p>在纯文本推理里，输入长度分布通常是一条带长尾的单峰曲线：绝大多数请求落在几百到几千 token，少数超长文档拖出尾巴。VLM 的图文请求不是这样。图像经目标模型视觉编码器前向、投影到语言模型嵌入空间后，视觉 token 数与文本提示长度是两个独立随机量，卷积起来就是双峰：短提示配单图（视觉 token 占主导）、长提示配多图或高分辨率切片（文本与视觉同时膨胀）。MASSV 的草稿模型消费的是“目标模型已产生的多模态上下文，含压缩后的视觉表示”，因此草稿侧上下文长度直接等于文本前缀加视觉 token 数，而不是文本长度。</p>\n<p>测量口径要可核查，就得把两段分开记。对每个请求记录四个量：文本提示 token 数 <span class=\"inline-math\">$n_t$</span>、视觉 token 数 <span class=\"inline-math\">$n_v$</span>、目标模型首 token 延迟 <span class=\"inline-math\">$T_{\\text{TTFT}}$</span>、草稿阶段每轮上下文长度 <span class=\"inline-math\">$n_t+n_v+\\text{已接受前缀}$</span>。分桶时按 <span class=\"inline-math\">$n_v$</span> 而不是按 <span class=\"inline-math\">$n_t+n_v$</span> 切，因为视觉编码段与解码段是两种不同性质的代价：前者是一次性、算力密集、与批内图像数线性相关；后者是迭代式、带宽与 KV cache 密集、与草稿轮数相关。把两者混进一个“输入长度”桶，测出来的 P99 无法归因。</p>\n<p>具体例子：同一套服务同时接图像问答（单图、短问句）与图像描述（单图、要求长输出）。前者 <span class=\"inline-math\">$n_v$</span> 大、<span class=\"inline-math\">$n_t$</span> 小、输出短，端到端延迟由视觉编码段主导；后者输出长，草稿轮数多，解码段主导。若只按总输入长度分桶，两类请求会落进同一桶，容量规划就会把视觉编码的固定开销错摊到解码吞吐上。MASSV 的收益恰恰在解码段——接受率越高，目标模型前向次数越少——所以分桶必须让解码段的收益可见，否则加速被视觉编码段的固定成本淹没。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-8\">八 · 并发与批大小：草稿模型与目标模型的批几何不一致</h3>\n<p>投机解码在批处理下有一个结构性矛盾：目标模型一次并行验证 k 个候选位置，批内每个请求的候选序列长度可以不同，但验证前向要把它们拼成一个批；草稿模型则是逐请求、逐轮地做轻量前向。MASSV 的结构里，视觉编码器只在目标模型侧运行一次，草稿模型复用视觉表示，这意味着草稿模型的批可以独立于目标模型的批来组织——但代价是两边的批几何必须各自满足显存与带宽约束。</p>\n<p>可核查的口径是“有效批大小”而非标称批大小。设批内请求 <span class=\"inline-math\">$i$</span> 的草稿轮数为 <span class=\"inline-math\">$r_i$</span>、每轮候选数 <span class=\"inline-math\">$k$</span>、平均接受前缀长度 <span class=\"inline-math\">$\\bar{a}_i$</span>，则目标模型在整段解码中的前向次数近似为</p>\n<div class=\"formula\">$$F_i \\approx \\frac{L_i}{\\bar{a}_i},\\qquad \\bar{a}_i = \\frac{1}{r_i}\\sum_{j=1}^{r_i} a_{i,j}$$</div>\n<p>其中 <span class=\"inline-math\">$L_i$</span> 是输出长度。批级吞吐取决于 <span class=\"inline-math\">$\\sum_i F_i$</span> 与每次验证前向的实际占用，而不是请求数。测量时要同时记 <span class=\"inline-math\">$\\bar{a}_i$</span> 的分布：接受前缀长度的方差大，说明批内请求的草稿质量参差，验证前向被最慢的那条拖住，批越大越明显。这就是负载反过来限制方案的第一条路径——高并发下批内异质性抬高验证前向的尾延迟，逼你把批切小或按 <span class=\"inline-math\">$n_v$</span> 与预期输出长度分池。</p>\n<p>显存侧的代价同样具体。草稿模型显存占用低于目标模型，可放低精度档位腾出 KV cache 空间；但草稿模型要消费视觉条件，其上下文里含视觉表示，视觉 token 数增大时草稿侧上下文变长，单请求的草稿激活显存随 <span class=\"inline-math\">$n_v$</span> 上升。批大小受限于“目标模型 KV cache + 草稿模型激活”的联合占用，而不是任一单项。工程判断：先按 <span class=\"inline-math\">$n_v$</span> 分桶定草稿侧批上限，再用目标模型 KV cache 余量定验证批上限，两个上限取小。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-9\">九 · SLO：首 token 延迟与每 token 延迟必须分开承诺</h3>\n<p>MASSV 的流程把一次请求切成三段：视觉编码器前向产出视觉 token、目标模型首前向产出首 token 与 KV、草稿-验证循环产出剩余 token。三段对应两个 SLO 指标，不能合并成一个端到端数字。首 token 延迟 <span class=\"inline-math\">$T_{\\text{TTFT}}$</span> 由视觉编码段加目标模型首前向决定，投机解码对它没有贡献——草稿模型在首 token 之后才介入。每 token 延迟 <span class=\"inline-math\">$T_{\\text{TPOT}}$</span> 才是接受率的函数：</p>\n<div class=\"formula\">$$T_{\\text{TPOT}} \\approx \\frac{T_{\\text{draft}}\\cdot k + T_{\\text{verify}}}{\\bar{a}}$$</div>\n<p>其中 <span class=\"inline-math\">$T_{\\text{draft}}$</span> 是草稿模型单轮前向时间、<span class=\"inline-math\">$T_{\\text{verify}}$</span> 是目标模型并行验证一次的时间。这个式子说明两件事：接受率 <span class=\"inline-math\">$\\bar{a}$</span> 提升直接压低 <span class=\"inline-math\">$T_{\\text{TPOT}}$</span>；而 <span class=\"inline-math\">$k$</span> 增大时草稿开销线性上升，若 <span class=\"$\\bar{a}$</span> 不随之上升，净收益转负。测量口径：对每个请求记录每轮 <span class=\"inline-math\">$k$</span>、接受前缀长度、草稿前向耗时、验证前向耗时，按 <span class=\"inline-math\">$n_v$</span> 桶聚合，得到 <span class=\"inline-math\">$T_{\\text{TPOT}}$</span> 对 <span class=\"inline-math\">$\\bar{a}$</span> 的敏感度曲线。</p>\n<p>长尾在这里的作用是决定 SLO 能不能兑现。MASSV 的蒸馏数据由目标模型在图文样本上自采样生成，覆盖图像问答与描述类负载；覆盖度决定分布外请求的接受率。长尾图文请求（罕见图像类型、异常提示结构、超长多图输入）落在蒸馏分布之外时，<span class=\"inline-math\">$\\bar{a}$</span> 下降，<span class=\"inline-math\">$T_{\\text{TPOT}}$</span> 上升，P99 尾延迟被拉长。可核查的做法是给接受率设一个分桶下限：某 <span class=\"inline-math\">$n_v$</span> 桶的 <span class=\"inline-math\">$\\bar{a}$</span> 低于阈值时，该桶请求退回非投机路径（目标模型直接解码），用吞吐换尾延迟稳定。这不是猜测，是把“长尾负载下接受率下降会抵消投机收益”这条材料结论落成调度规则。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-10\">十 · 负载塑造方案：分桶、回退与草稿档位</h3>\n<p>负载形态反过来约束方案设计，最直接的三条：</p>\n<ul>\n<li>按 <span class=\"inline-math\">$n_v$</span> 分桶决定草稿模型上下文上限。视觉 token 数增长抬高草稿侧上下文开销，桶上限决定单请求草稿激活显存，进而决定并发上限。</li>\n<li>按预期输出长度分池。短输出请求的草稿轮数少，投机收益被视觉编码固定成本稀释；长输出请求才是 <span class=\"inline-math\">$\\bar{a}$</span> 收益的主战场。两池用不同 <span class=\"inline-math\">$k$</span> 与不同批大小。</li>\n<li>接受率回退阈值。分布外请求 <span class=\"inline-math\">$\\bar{a}$</span> 低于阈值即切回目标模型直接解码，避免“草稿白跑、验证照做”的双重开销。</li>\n</ul>\n<p>草稿模型放低精度档位是显存侧的杠杆：草稿只做轻量前向，低精度对其分布逼近能力的影响由自数据蒸馏的监督信号约束——训练目标是最小化草稿分布与目标分布在视觉条件下的差异，目标模型权重冻结、保持验证精度，因此输出一致性由目标模型侧保证。代价是低精度草稿的接受率可能低于高精度草稿，这是一个可测的权衡：同一批图文请求上分别测两种档位的 <span class=\"inline-math\">$\\bar{a}$</span> 与草稿显存，取满足 SLO 的最低精度档。</p>\n<p>具体例子：一个图像问答服务，<span class=\"inline-math\">$n_v$</span> 集中在单图量级，输出长度短。若把草稿模型与目标模型同卡部署，草稿激活挤占 KV cache，验证批上限下降，吞吐反而低于不投机。此时正确做法是把草稿模型分离部署或压到更低精度档，把省出的显存全部给 KV cache，让验证批做大——负载形态（短输出、高并发）决定了方案必须优先保验证吞吐而不是草稿精度。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-11\">十一 · 方案反过来限制负载：KV 回退与一致性边界</h3>\n<p>反向约束同样真实。MASSV 的验证阶段接受最长一致前缀，被拒位置由目标分布重采样，接受前缀写入 KV cache、被拒部分回退到接受长度。这条机制给负载设了一个硬边界：回退与重采样的正确性决定输出与目标模型单独解码的等价性，任何为了吞吐而放宽回退一致性的调度（例如跨请求共享 KV 前缀、异步预取下一轮草稿）都必须证明不破坏该等价性。可核查口径是逐请求比对投机输出与目标模型直接解码输出，逐 token 一致率必须是 1；不一致即视为调度 bug，不是精度问题。</p>\n<p>第二个边界是草稿轮数与上下文增长的耦合。每接受一轮，草稿侧上下文加长 <span class=\"inline-math\">$\\bar{a}$</span> 个 token，草稿前向的注意力开销随上下文线性上升；长输出请求跑到后期，草稿前向可能不再是“轻量”。测量上要记录草稿前向耗时随已生成长度的斜率，斜率显著为正说明草稿侧上下文成了瓶颈，此时应缩短 <span class=\"inline-math\">$k$</span> 或提前终止投机、让目标模型接管剩余解码。</p>\n<p>第三个边界来自视觉编码段的不可摊薄性。视觉编码器只在目标模型侧运行一次，草稿模型复用其视觉表示——这摊薄了编码开销，但也意味着视觉编码段是请求进入时的串行瓶颈，批内图像数决定该段耗时。高并发下若视觉编码段成为 <span class=\"inline-math\">$T_{\\text{TTFT}}$</span> 的主项，增加草稿模型精度或增大 <span class=\"inline-math\">$k$</span> 都不会改善首 token 延迟；容量规划必须把视觉编码吞吐与解码吞吐当作两个独立资源来配，前者按图像数、后者按 <span class=\"inline-math\">$\\sum_i F_i$</span>。</p>\n<p>落到工程判断：MASSV 的净收益是 <span class=\"inline-math\">$\\bar{a}$</span> 的函数，而 <span class=\"inline-math\">$\\bar{a}$</span> 是负载分布的函数。部署前必须先在真实图文流量上测出按 <span class=\"inline-math\">$n_v$</span> 与输出长度分桶的接受率矩阵，再据此定分桶、回退阈值与草稿精度档；材料未给出接受率与加速比数字，任何容量结论只能来自这套实测口径，而不是从文本域投机解码的经验外推。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-12\">十二 · 负载形态如何反噬方案：从图文请求分布到投机收益的边界</h3>\n<p>MASSV 的收益不是常数，而是请求分布的因变量。图文请求的输入长度由图像 token 数主导，视觉 token 越多，草稿模型要消费的多模态上下文越长，单轮预测的轻量前向也随之变重；而视觉编码器只在目标模型侧运行一次，其开销被摊薄到整段解码，摊薄程度取决于解码长度。设视觉编码前向耗时为 <span class=\"formula-inline\">$T_{\\text{vis}}$</span>，目标模型单次验证前向为 <span class=\"formula-inline\">$T_{\\text{tgt}}$</span>，草稿模型单轮前向为 <span class=\"formula-inline\">$T_{\\text{draft}}$</span>，每轮接受前缀长度为 <span class=\"formula-inline\">$a$</span>，则每 token 的有效代价近似为 <div class=\"formula\">$$\\frac{T_{\\text{vis}} + N_{\\text{round}}\\,(T_{\\text{draft}} + T_{\\text{tgt}})}{\\sum a_i}$$</div>分母是总接受 token 数，<span class=\"formula-inline\">$N_{\\text{round}}$</span> 为验证轮数。短描述类请求解码步数少，<span class=\"formula-inline\">$T_{\\text{vis}}$</span> 摊不薄，投机收益被视觉段吃掉；长问答解码步数多，摊薄充分，但草稿上下文随视觉 token 线性增长，<span class=\"formula-inline\">$T_{\\text{draft}}$</span> 上升。两端都是失效区，中间才是净收益区。</p>\n<p>并发与批大小进一步改写这个式子。草稿模型与目标模型若同卡部署，草稿的低精度权重会挤占 KV cache 空间；若分离部署，则每轮验证都要跨卡搬运候选 token 与被拒位置的重采样请求，通信开销进入 <span class=\"formula-inline\">$T_{\\text{tgt}}$</span> 的有效项。按视觉 token 数量分桶批处理能压平草稿上下文长度的方差，但桶边界本身会制造排队长尾：大视觉 token 请求落入高桶后等待同桶伙伴，首 token 延迟（TTFT）被拉长，而 SLO 恰恰把视觉编码段与解码段分开计量，TTFT 超标无法用解码段的加速比补偿。可核查的口径应至少记录四项：按图像 token 数分桶的请求占比、每桶的并发与批大小、每请求的视觉编码耗时与解码耗时之比、以及每轮接受前缀长度 <span class=\"formula-inline\">$a$</span> 的分布（均值不足以刻画长尾，需看低分位）。</p>\n<p>长尾图文负载是接受率的结构性风险。蒸馏数据由目标模型在图文样本上自采样生成，覆盖度决定草稿分布在分布外请求上的逼近程度；罕见版式、密集小字、多图对照这类请求若不在自采样分布内，草稿模型在视觉条件下的下一 token 分布偏离目标，接受率下降，<span class=\"formula-inline\">$a$</span> 塌缩到接近 1，投机退化为每轮一次目标前向加一次无效草稿前向，端到端延迟反而高于不用投机。这正是方案反过来限制负载的地方：服务方要么在路由层把低置信请求切回普通解码，要么扩充自采样覆盖，二者都以吞吐或数据成本为代价。工程判断落在监控上——把接受率、每轮接受前缀长度与目标模型前向次数作为一等指标，按请求桶与图像 token 分位切片，一旦某切片接受率跌破阈值即触发降级路由；同时校验 KV cache 回退长度与重采样位置的一致性，回退错位会破坏与目标模型单独解码的等价性，这种错误在长尾负载下更难复现。</p>\n<table class=\"mini\"><thead><tr><th>负载切片</th><th>主导代价</th><th>失效条件</th></tr></thead><tbody><tr><td>短描述、少视觉 token</td><td>视觉编码摊薄不足</td><td>解码步数少，投机净收益为负</td></tr><tr><td>长问答、多视觉 token</td><td>草稿上下文变长</td><td>草稿前向抵消验证节省</td></tr><tr><td>分布外长尾图文</td><td>接受率塌缩</td><td>每轮仅接受 1 token，退化</td></tr></tbody></table>\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-13\">十三 · 草稿侧轻量前向的算子选型与精度档位</h3>\n<p>MASSV 的草稿模型只做单步或多步预测，其前向计算量远小于目标 VLM，因此在 Blackwell 上它天然适合被压到低精度档位。但“能压”不等于“随便压”：草稿模型的输出分布要与目标模型在视觉条件下逐位可比，验证阶段比较的是两个分布的一致性，草稿侧任何系统性数值偏移都会直接表现为接受率下降。工程上要把草稿模型的算子分成两类对待——投影与归一化（LayerNorm、视觉到语言嵌入的线性投影）对量化误差敏感，因为视觉 token 的嵌入幅值分布与文本 token 差异大，低精度下的截断会改变条件分布的均值；而草稿解码器里的 GEMM 与注意力打分矩阵乘则可以安全地走 FP8 甚至 NVFP4，因为它们只影响候选 token 的相对排序，被拒位置最终由目标分布重采样兜底。</p>\n<p>Blackwell 第五代 Tensor Core 的微缩放格式在这里给出了一条明确的路径。NVFP4 采用 16 元素一块、共享一个 FP8 缩放因子的分块量化，块内再配 FP8 的二级缩放，使得视觉 token 这种长尾分布（少数高幅值 patch 与大量低幅值背景 patch 并存）不会因单一全局缩放而整体塌陷。对草稿模型的权重与激活同时做 NVFP4，显存占用相对 BF16 降到约四分之一，这部分腾出的空间直接让给目标模型的 KV cache——在多模态负载里 KV cache 随图像 token 数线性增长，是显存的主要压力源。代价是草稿侧 GEMM 的累加必须在 FP32 上完成，若累加器降到 FP16，长序列上的误差累积会让草稿分布尾部概率失真，接受前缀长度缩短。</p>\n<div class=\"formula\">$$\\hat{y} = \\sum_{i} \\text{dequant}(w_i^{q}, s_{\\text{block}}) \\cdot \\text{dequant}(a_i^{q}, s_{\\text{block}}),\\quad \\text{acc} \\in \\text{FP32}$$</div>\n<p>逐项解释：$w_i^{q}$、$a_i^{q}$ 是块内量化后的权重与激活整数，$s_{\\text{block}}$ 是该 16 元素块共享的 FP8 缩放因子，dequant 把整数还原到可乘的浮点域，求和累加器固定为 FP32。这个式子的工程含义是：精度损失集中在“量化—反量化”这一步，而累加精度决定了误差是否随序列长度放大。草稿模型层数浅、序列短，FP32 累加的开销在 Blackwell 上被 tcgen05 的吞吐掩盖，不构成瓶颈。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-14\">十四 · tcgen05、TMEM 与 2-SM MMA 在草稿解码中的落点</h3>\n<p>Blackwell 的 tcgen05 指令族把矩阵乘的累加器从寄存器文件搬到了 Tensor Memory（TMEM）——一块与 Tensor Core 紧耦合、容量远大于寄存器堆的片上存储。对草稿模型的意义在于：投机解码的草稿阶段是典型的“小 batch、短序列、多轮迭代”形态，每轮只预测 k 个 token，若累加器仍放在寄存器里，寄存器压力会限制同时驻留的 warp 数，进而压低占用率。把累加器放进 TMEM 后，草稿模型可以在同一 SM 上并行推进多个请求的草稿前向，而不必为每个请求复制一份寄存器上下文。这在连续批处理下直接转化为吞吐：草稿阶段不再是被寄存器容量卡住的串行段。</p>\n<p>2-SM MMA（两 SM 协同的矩阵乘）则对应草稿模型里较大的那部分 GEMM——视觉条件注入后的跨模态注意力投影。两个 SM 通过共享的 TMEM 视图协作完成一次 MMA，等效于把单次矩阵乘的 tile 做大，减少因 tile 过小导致的流水线气泡。代价是配对的两个 SM 必须同步进入该指令，调度器要把它们绑定在同一 CTA cluster 内，这会让批调度器在分配草稿请求时必须以偶数 SM 为单位成对投放，碎片化的尾批因此更难填满。对多模态负载而言，图像 token 数差异大，请求长度参差，成对投放会放大尾延迟——这是草稿侧使用 2-SM MMA 时必须与批调度联动评估的代价。</p>\n<table class=\"mini\"><thead><tr><th>草稿阶段算子</th><th>精度档位</th><th>Blackwell 特性</th><th>主要代价</th></tr></thead><tbody><tr><td>跨模态注意力投影 GEMM</td><td>FP8</td><td>2-SM MMA + TMEM 累加</td><td>SM 成对绑定，尾批碎片化</td></tr><tr><td>草稿解码器 FFN</td><td>NVFP4 权重 / FP8 激活</td><td>tcgen05 分块缩放</td><td>反量化开销，需 FP32 累加</td></tr><tr><td>LayerNorm 与嵌入投影</td><td>BF16</td><td>—</td><td>保持视觉条件均值不失真</td></tr></tbody></table>\n<p>具体例子：一个图像问答请求带数百个视觉 token，草稿模型每轮预测 k 个候选。跨模态投影若走 2-SM MMA，单次 tile 增大使该投影的流水线利用率提升；但若同一批里混入只有几十个视觉 token 的短请求，成对 SM 的绑定会让短请求等待配对，草稿阶段的实际延迟由批内最长请求决定。这就是为什么草稿模型的算子选型不能脱离批形态单独讨论。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-15\">十五 · 视觉条件的数值通路：从目标侧编码到草稿侧消费</h3>\n<p>MASSV 的结构决定了一条不对称的数值通路：视觉编码器只在目标模型侧运行一次，草稿模型复用其视觉表示。这条通路上的精度决策比草稿解码器本身更关键，因为视觉表示是草稿模型唯一的多模态条件输入，它的数值保真度决定了草稿分布能否对齐目标分布在图像条件下的偏移。目标侧视觉编码器输出通常是 FP16/BF16，投影到语言嵌入空间后与文本嵌入拼接。若草稿模型以 NVFP4 消费这份视觉表示，投影层的量化误差会改变条件向量的方向，草稿模型对图像内容的敏感度下降，表现为在需要细粒度视觉 grounding 的问题上接受率走低。</p>\n<p>工程判断是分层处理：视觉表示进入草稿模型的第一层投影保持 BF16，之后的草稿解码器内部才降到 FP8/NVFP4。这样草稿模型“看得见”视觉条件的高保真版本，而内部计算仍享受低精度吞吐。代价是这份 BF16 视觉表示要在草稿侧常驻，其显存占用与视觉 token 数成正比；当图像分辨率高、token 数大时，这份常驻表示会挤占本已紧张的 KV cache 空间。缓解手段是把视觉表示按请求生命周期管理——验证阶段接受前缀写入 KV cache 后，草稿侧只需保留当前轮的视觉条件，历史轮的视觉表示可释放。</p>\n<div class=\"formula\">$$p_{\\text{draft}}(x_t \\mid x_{&lt;t}, v) = \\text{softmax}\\left(\\frac{W_{\\text{lm}}\\,\\text{Dec}(\\text{proj}_{\\text{BF16}}(v),\\, x_{&lt;t})}{T}\\right)$$</div>\n<p>逐项解释：$v$ 是目标侧视觉编码器输出，$\\text{proj}_{\\text{BF16}}$ 是高保真投影，$\\text{Dec}$ 是低精度草稿解码器，$W_{\\text{lm}}$ 是输出头，$T$ 是蒸馏温度。式子的含义是：条件通路的精度（BF16 投影）与内部计算的精度（低精度 Dec）解耦，前者保分布对齐、后者保吞吐。蒸馏温度 $T$ 影响草稿分布的平滑度，温度过高会让草稿分布过度平坦、与目标分布的逐位比较更难通过，温度过低则草稿过于自信、被拒时回退代价大。材料未给出具体温度取值，部署时需按接受率与回退率联合调。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-16\">十六 · 验证阶段的并行前向与累加误差的耦合</h3>\n<p>验证阶段目标模型对 k 个候选位置做一次并行前向，逐位比较草稿分布与目标分布。这里的数值问题是双向的：目标模型侧的验证前向若也用了低精度（例如目标模型的部分层走 FP8），其输出分布本身就带量化噪声，与草稿分布的逐位比较会把噪声误判为不一致，压低接受前缀长度。MASSV 的设定是目标模型权重冻结、保持验证精度，这正是为了避免验证侧的数值漂移污染接受判定。草稿侧的低精度误差可以容忍，因为被拒位置由目标分布重采样兜底；验证侧的低精度误差不可容忍，因为它直接定义了“一致”的判据。</p>\n<p>并行前向的另一个代价在 KV cache 的回退。接受最长一致前缀后，被拒位置的 KV 要回退到接受长度，回退的正确性依赖目标模型前向时写入的 KV 与草稿 token 的位置编码严格对应。若验证前向为了并行校验而把 k 个位置一次性算完，其 KV 布局与逐位解码时的布局必须一致，否则回退后重采样会读到错位的历史。这在数值上表现为：回退后的重采样分布与目标模型单独解码在同一位置的分布出现偏差，输出等价性被破坏。工程上要把验证前向的 KV 写入做成“先写后裁”——先按 k 个位置写入，再按接受长度截断，截断操作必须是幂等的。</p>\n<p>具体例子：一轮草稿预测 k 个 token，目标模型并行前向产出 k 组分布，逐位比较后接受前 m 个（m ≤ k）。KV cache 从当前位置加 k 截断到加 m，被拒的 k−m 个位置的 KV 丢弃，由目标分布在位置 m 处重采样一个 token 并写入。若截断时位置编码没有同步回退，下一轮草稿模型读到的前缀位置就会错位，草稿分布整体偏移，接受率在后续轮次持续走低——这是一种会自我强化的失败模式。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-17\">十七 · 精度档位与接受率的联合调优</h3>\n<p>草稿模型的精度档位不是孤立的技术选择，它与接受率构成一条可观测的调优回路。把草稿解码器从 BF16 降到 FP8，草稿前向吞吐上升、显存下降，但草稿分布与目标分布的逐位一致性会轻微退化，接受前缀长度缩短，目标模型前向次数增加。净收益取决于两者的乘积：草稿阶段省下的时间是否大于验证阶段多出的前向。在多模态负载里，视觉编码段是固定开销、被摊薄到整段解码，解码段的每 token 延迟才是 SLO 的主导项，因此草稿侧降精度换来的吞吐必须真正转化为更短的验证轮次，否则只是把计算从草稿挪到了验证。</p>\n<p>可操作的监控指标是每轮接受前缀长度与目标模型前向次数的比值。当草稿侧降一档精度后该比值下降超过草稿前向时间的节省，就应回退档位。NVFP4 的引入要更谨慎：它适合草稿解码器的 FFN 权重，因为 FFN 的输出只影响候选 token 的打分排序；不适合输出头 $W_{\\text{lm}}$，因为输出头直接生成草稿分布，其量化误差会系统性地偏移整个分布。把输出头保持在 FP8 或 BF16，是草稿侧低精度化的一条硬边界。</p>\n<ul><li>草稿 FFN 与注意力打分：NVFP4/FP8，FP32 累加，收益在吞吐与显存。</li><li>视觉条件投影：BF16，保分布对齐，代价是常驻显存。</li><li>输出头：FP8 及以上，避免分布系统性偏移。</li><li>目标模型验证前向：保持验证精度，不接受低精度化。</li></ul>\n<p>落到工程判断上：MASSV 在 Blackwell 上的精度策略应围绕“条件通路高保真、内部计算低精度、验证侧不降级”三条线组织。草稿模型的低精度档位腾出的显存要显式分配给 KV cache，而不是留给草稿模型自身扩容；视觉表示的常驻生命周期要跟随请求轮次回收；验证前向的 KV 写入与截断要保证幂等。这三条线任何一条松动，接受率的下降都会吞掉低精度带来的吞吐收益，投机解码的净加速随之消失。</p>\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-18\">十八 · 显存账本的三本账：权重、激活、KV</h3>\n<p>在 Blackwell 上给 MASSV 做容量规划，第一件事不是算加速比，而是把一张卡（或一个 NVL72 机柜里的一个 GPU 切片）的 HBM3e 拆成三本互不侵占的账：目标 VLM 权重、草稿模型权重与运行时激活、KV cache。三者的增长规律完全不同——权重是常量，激活随批大小与视觉 token 数线性涨，KV cache 随「并发 × 上下文长度 × 层数 × KV 头数 × 头维度 × 精度字节」线性涨，而且它是唯一会随请求数持续膨胀的一项。MASSV 的结构决定了账本的特殊性：视觉编码器只在目标模型侧跑一次，草稿模型复用目标模型已产出的压缩视觉表示，因此草稿侧没有独立的视觉激活峰值；但草稿模型必须在每一轮解码里持有「视觉条件 + 已接受前缀」的上下文，这段上下文在草稿侧也要占一份 KV 或至少一份条件缓存。</p>\n<p>可复算的预算写成下面这个形式，单位统一为 GiB：</p>\n<div class=\"formula\">$$M_{\\text{total}} = \\underbrace{W_{\\text{tgt}} + W_{\\text{draft}}}_{\\text{权重}} + \\underbrace{A_{\\text{vis}} + A_{\\text{dec}}(b)}_{\\text{激活}} + \\underbrace{K_{\\text{tgt}} + K_{\\text{draft}}}_{\\text{KV}} + M_{\\text{workspace}}$$</div>\n<p>其中 $K = 2 \\cdot L \\cdot H_{kv} \\cdot d_h \\cdot s \\cdot b \\cdot \\beta$，$\\beta$ 是每元素字节数（FP8 为 1，NVFP4 为 0.5 加缩放因子开销），$s$ 是含视觉 token 的上下文长度。工程判断的顺序是：先扣掉两份权重和固定 workspace，剩下的才是 KV 可用池；再用 KV 池除以单请求 KV 占用，得到并发上限。MASSV 的收益恰恰体现在这里——草稿模型可放低精度档位，权重与草稿侧 KV 都变薄，把省下来的容量还给目标模型的 KV 池，从而抬高并发；但草稿模型上下文随视觉 token 数增长，长图文请求会吃掉这部分红利。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-19\">十九 · 视觉 token 是 KV 账本里的隐形放大器</h3>\n<p>文本请求的 KV 增长是渐进的，视觉请求不是：图像经视觉编码器与投影后一次性注入一大段视觉 token，这段 token 在目标模型与草稿模型两侧都要进上下文。以一张被切成若干 patch 的图为例，视觉 token 数由编码器 patch 尺寸与是否做 token 压缩决定，MASSV 材料只说明草稿模型消费的是「压缩后的视觉表示」，未给出具体压缩率，因此预算必须按最坏情况（未压缩或轻度压缩）留余量。设文本前缀 $s_t$、视觉 token $s_v$，则单请求 KV 为 $K(s_t + s_v)$，视觉段贡献的比例是 $s_v/(s_t+s_v)$；当 $s_v$ 与 $s_t$ 同量级时，KV 占用直接翻倍，并发上限腰斩。</p>\n<p>更麻烦的是分页粒度。连续批处理按块（block）分配 KV，块大小通常取 16 或 32 token；视觉 token 段往往不能被块大小整除，尾部产生内部碎片。若一个请求的视觉段是 576 token、块大小 32，则恰好 18 块无碎片；若是 580 token，则多出 1 块、浪费 28 个槽位。高并发下这种碎片按请求数累积，等效于把可用 KV 池缩小若干百分点。工程上的做法是把视觉 token 数按块大小向上取整后作为分桶键，让调度器按「视觉块数 + 文本块数」而不是按原始 token 数计费，避免同一批里混入块数差异过大的请求。</p>\n<p>代价落在延迟上：视觉段越长，目标模型首次前向的注意力计算越重，首 token 延迟（TTFT）上升；而草稿模型每轮都要在这段长上下文上做轻量前向，其单步开销随 $s_v$ 线性增长，接受率带来的收益被草稿侧成本部分抵消。这正是 MASSV 局限里点明的「视觉 token 数量增大时草稿模型上下文变长，抵消部分投机解码收益」的显存侧对应物。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-20\">二十 · 分页、压缩、复用、卸载：四种手段的边界</h3>\n<p>分页（paged KV）解决的是碎片与动态增长：把 KV 切成固定大小的块，用块表映射逻辑位置到物理块，请求结束即回收。它对 MASSV 的直接价值是让「接受前缀写入、被拒部分回退」变成块表指针的回退而非数据搬移——回退到接受长度只需把块表截断，被拒位置的槽位标记为空闲，下一轮重采样直接覆写。这里有一个必须守住的正确性条件：回退后的 KV 必须与「只解码到接受前缀」的状态逐位一致，否则目标模型的验证分布会漂移，输出等价性被破坏。实现上要求在写入草稿 token 的 KV 时保留其来源标记，回退时按标记清除，而不是按位置盲删。</p>\n<p>压缩分两档：KV 量化（FP8 甚至 NVFP4 存 KV，配合 per-block 缩放）与 token 级淘汰（丢弃低注意力权重的历史 token）。前者省容量、省带宽，代价是注意力输出的数值误差；后者省得更多但会改变分布，在投机解码场景下尤其危险——目标模型验证时用的 KV 若与草稿模型假设的 KV 不一致，接受率会异常下降。MASSV 的草稿模型消费的是目标模型侧的视觉表示，因此视觉段的 KV 压缩策略必须两侧共享同一份量化参数，不能各自为政。</p>\n<p>复用指前缀缓存（prefix caching）：同一张图被多个请求引用时，视觉段 KV 可跨请求共享，只计算一次。图文问答负载里同一图多问题的形态很常见，前缀缓存能把视觉段的 KV 与计算成本摊薄到多次请求。代价是缓存命中判断与块表引用计数，以及缓存池本身要占容量——命中率低时反而挤占 KV 池。</p>\n<p>卸载（offload）把冷 KV 或草稿模型权重放到主机内存甚至 NVLink 对端 GPU。Blackwell 的 HBM3e 容量有限而 NVLink 5 带宽高，把草稿模型整体放到另一张卡、按轮次拉取激活是可行路径，但每轮解码都要跨卡同步草稿输出与目标验证结果，通信延迟会进入每 token 延迟的关键路径。工程判断是：只有当草稿模型权重与 KV 确实挤占了目标模型并发所需容量、且跨卡往返延迟远小于目标模型单次前向时，卸载才划算。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-21\">二十一 · 带宽瓶颈在哪：HBM 读放大与验证前向</h3>\n<p>解码阶段的算术强度极低：每生成一个 token，目标模型要把全部权重从 HBM 读一遍（或按层分片读），而计算量只有一次矩阵向量乘。因此 decode 的瓶颈是 HBM 带宽而非算力。MASSV 把目标模型前向次数从「每 token 一次」降到「每接受前缀一次」，直接减少的是权重读放大次数——这是它省带宽的根本机制，而不是省算力。设每轮草稿预测 $k$ 个 token、接受前缀长度 $\\ell$，则目标模型前向次数约为 $N/\\ell$（$N$ 为总生成 token 数），权重读取总量同比下降；草稿模型每轮做 $k$ 步轻量前向，其权重远小于目标模型，读放大可忽略，但它的 KV 读取随上下文长度增长。</p>\n<div class=\"formula\">$$T_{\\text{decode}} \\approx \\frac{N}{\\ell}\\cdot\\frac{W_{\\text{tgt}}}{BW_{\\text{HBM}}} + N\\cdot\\frac{W_{\\text{draft}}}{BW_{\\text{HBM}}} + T_{\\text{verify-overhead}}$$</div>\n<p>这个式子说明：接受率（决定 $\\ell$）是带宽收益的唯一杠杆；$\\ell$ 接近 1 时草稿侧开销纯属净亏。验证阶段目标模型对 $k$ 个候选位置做一次并行前向，其注意力要对 $k$ 个位置同时算，KV 读取量约为单 token 前向的 $k$ 倍但只做一次权重读——这正是投机解码在带宽受限下划算的原因。代价是验证前向的激活峰值随 $k$ 增长，$k$ 取太大时激活账本会挤压 KV 池，形成「草稿步数 ↔ 并发」的权衡。</p>\n<p>Blackwell 的 HBM3e 容量按每 GPU 的堆栈数与单堆栈容量计算，机柜级 GB200/GB300 NVL72 把 72 个 GPU 的 HBM 聚合成一个逻辑池。容量算账时要注意：NVL72 的聚合容量不等于单请求可用容量，因为张量并行会把权重与 KV 按层切分到多卡，单卡可用 KV 池要按切分后的份额算，而不是按聚合总量算。工程上先按单卡预算做并发上限，再用 NVLink 域内的前缀缓存共享与草稿模型分离部署去调优，而不是一上来就按机柜总量估并发。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-22\">二十二 · 一个可复算的显存预算（示例口径）</h3>\n<p>下面给出一张单卡预算表的骨架，所有项都写成「符号 × 口径」，读者代入自己模型的层数、KV 头数、头维度与精度即可复算。表中不填具体数值，因为材料未给出模型规模与硬件档位；填的是计算方式与占位关系。</p>\n<table class=\"mini\">\n<thead><tr><th>账目</th><th>计算口径</th><th>随什么增长</th><th>MASSV 相关动作</th></tr></thead>\n<tbody>\n<tr><td>目标模型权重</td><td>参数量 × 每参数字节（验证精度）</td><td>常量</td><td>冻结，不因蒸馏改变</td></tr>\n<tr><td>草稿模型权重</td><td>草稿参数量 × 低精度字节</td><td>常量</td><td>放低精度档位腾容量</td></tr>\n<tr><td>视觉激活峰值</td><td>编码器 patch 数 × 通道 × 批</td><td>批大小、图像分辨率</td><td>只在目标侧跑一次</td></tr>\n<tr><td>解码激活</td><td>批 × 隐维 × 层间缓冲</td><td>批大小、验证步数 k</td><td>k 越大峰值越高</td></tr>\n<tr><td>目标 KV</td><td>2·L·H_kv·d_h·(s_t+s_v)·b·β</td><td>并发、上下文、视觉 token</td><td>接受前缀写入、被拒回退</td></tr>\n<tr><td>草稿 KV/条件缓存</td><td>同上但 L、H_kv 更小</td><td>并发、视觉条件长度</td><td>复用目标视觉表示</td></tr>\n<tr><td>workspace</td><td>通信缓冲、块表、临时区</td><td>并行度、块数</td><td>按固定比例预留</td></tr>\n</tbody>\n</table>\n<p>复算步骤：第一步，用总容量减去两份权重、视觉激活峰值与 workspace，得到 KV 可用池 $M_{KV}$。第二步，按最坏视觉 token 数 $s_v^{\\max}$ 与目标文本长度上限算单请求 KV 占用 $K_{\\text{req}}$，并发上限 $b_{\\max}=\\lfloor M_{KV}/K_{\\text{req}}\\rfloor$。第三步，把草稿模型精度降一档，重算 $W_{\\text{draft}}$ 与草稿 KV，观察 $b_{\\max}$ 的增量——这个增量就是 MASSV 在容量侧的净收益上界。第四步，用分页块大小对 $s_v$ 向上取整，重算碎片损耗，若损耗超过若干百分点则调整分桶策略。</p>\n<p>举例说明口径：若某 VLM 的视觉段在未压缩时与文本前缀同量级，则单请求 KV 中视觉段占一半；此时把草稿模型从验证精度降到低精度，省下的权重容量若相当于若干个请求的 KV，则并发上限提升的幅度取决于草稿 KV 是否也同步变薄。若草稿侧仍以高精度存视觉条件缓存，则容量红利被抵消——这正是「草稿模型可放在低精度档位以降低显存占用」这条事实在预算表里的落点。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-23\">二十三 · 回退一致性与容量规划的耦合</h3>\n<p>KV 回退不是纯容量问题，它和预算表里的「目标 KV」一行直接耦合。被拒位置由目标分布重采样后，这些位置的 KV 必须被覆盖而不是保留，否则下一轮草稿模型会读到「从未被接受却被写入」的历史，其条件分布偏离目标分布，接受率进一步下降，形成负反馈。实现上，回退要在块表层面截断，并在重采样写入时把新 token 的 KV 覆盖到同一逻辑位置；若采用前缀缓存共享，还要处理引用计数——被回退的块若被其他请求共享，不能直接释放，只能标记为「本请求不再引用」。</p>\n<p>容量规划因此要留出一份「回退余量」：每轮验证的 $k$ 个候选位置在写入 KV 时是乐观写入（先写后验），被拒部分随后回退，峰值占用比稳态多出最多 $k-1$ 个位置的 KV。高并发下这份瞬时峰值乘以并发数不可忽略，预算表里应把它计入 workspace 或直接在 KV 池里按 $k$ 个 token 的块数预留。工程判断是：$k$ 的取值不能只看接受率曲线，还要看它对 KV 峰值的乘数效应；在 HBM3e 容量吃紧、并发目标高的部署里，宁可取小 $k$、多轮验证，也不要让回退余量把并发上限压下去。</p>\n<p>最后落到一个具体机制上：把「视觉块数 + 文本块数 + 回退预留块数」作为调度器的计费单位，而不是按原始 token 数计费，可以让 MASSV 的草稿-验证循环在分页 KV 上稳定运行——接受前缀的写入与被拒回退都变成块表操作，容量账本在请求生命周期内保持可预测，视觉 token 带来的长上下文开销被显式计入而不是隐性挤占并发。</p>\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-24\">二十四 · 连续批处理下的草稿-验证耦合</h3>\n<p>在 MASSV 的推理路径里，连续批处理（continuous batching）不是把请求攒够一批再统一跑，而是每个解码步都重新组批：已完成的序列退出、新到的图文请求插入。问题在于，投机解码把「一步」拆成了草稿前向与目标验证两个子步，二者的批组成必须一致——草稿模型为批内每条序列生成 k 个候选 token，目标模型随后对同一批的 k 个位置并行验证。若在草稿与验证之间插入新请求，新序列没有候选 token，验证步的批形状就会参差，tcgen05 MMA 的 tile 利用率随之塌陷。</p>\n<p>工程上的做法是把批组装的粒度锁在「草稿-验证对」上：调度器只在验证步结束后才接纳新序列，草稿步与验证步共享同一份序列集合。代价是接纳延迟被拉长到一个完整的投机轮次，队列等待时间增加；收益是验证步的批内每条序列都贡献 k 个待验证位置，目标模型一次前向的有效 token 数被放大 k 倍，摊薄了权重读取的带宽开销。对 Blackwell 上的大权重目标模型，这一步的带宽节省比接纳延迟更值钱。</p>\n<p>伪代码思路如下：每个调度周期先冻结批集合 <span>B</span>，对 <span>B</span> 中每条序列跑草稿模型得候选集 <span>C_i</span>，再把 <span>{(prefix_i, C_i)}</span> 拼成验证批送目标模型，接受前缀长度 <span>a_i</span> 回写 KV cache 并释放被拒槽位。批内序列的 <span>a_i</span> 差异越大，验证步的浪费越大——一条序列只接受 1 个 token，另外 k−1 个位置的验证算力就白烧。因此连续批处理在 VLM 场景下要额外做「接受率感知的批内配对」：把历史接受率相近的请求放进同一批，避免高接受率序列被低接受率序列拖慢。</p>\n<p>具体例子：一个图像问答请求与一个长图像描述请求同批。描述类负载的草稿接受率通常低于短问答，因为描述文本的分布更发散。若二者同批，验证步按最长候选序列对齐，短问答序列被迫陪跑多余位置，每 token 延迟被拉高。按负载形态分桶组批，能把批内 <span>a_i</span> 的方差压下来。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-25\">二十五 · Chunked prefill 与视觉编码段的切分</h3>\n<p>VLM 的预填段与纯文本模型不同：它包含视觉编码器前向与语言侧 prefill 两段，前者只在目标模型侧跑一次，后者要把视觉 token 与文本 token 拼成的长上下文灌进 KV cache。chunked prefill 的作用是把长 prefill 切成若干块，与解码步交错执行，避免一个超长图文请求独占整个 GPU 造成解码请求的尾延迟尖峰。</p>\n<p>切分点的选择有讲究。视觉编码器输出投影到语言嵌入空间后，视觉 token 与文本 token 在序列里是连续的，切块应落在视觉段与文本段的边界或文本段内部，不应把视觉 token 块拆到两个 chunk 里——草稿模型消费的是目标模型已产出的多模态上下文，视觉表示若跨 chunk 尚未完整写入 KV，草稿步就无法取得一致的视觉条件。因此调度器要把「视觉段完整入 KV」作为该请求进入草稿阶段的前置条件。</p>\n<div class=\"formula\">$$T_{\\text{prefill}} = \\left\\lceil \\frac{L_v + L_t}{C} \\right\\rceil \\cdot t_{\\text{chunk}} + (N_{\\text{chunk}}-1)\\cdot t_{\\text{decode}}$$</div>\n<p>其中 <span>L_v</span> 为视觉 token 数、<span>L_t</span> 为文本 token 数、<span>C</span> 为 chunk 容量。块数越多，解码请求被插入的机会越多，尾延迟越平滑，但每块的目标模型前向都带着固定的权重读取开销，块太小则总吞吐下降。Blackwell 上这个权衡落在「块容量刚好填满一个 MMA tile 组」附近，再小就只剩启动开销。</p>\n<p>代价体现在显存侧：chunked prefill 要求 KV cache 分块分配，未完成的 chunk 占用预留槽位，长图文请求在 prefill 期间持有的 KV 页数高于其最终长度对应的页数。并发高时这部分预留会挤压解码请求的 KV 空间，触发抢占。因此 chunk 容量要与 KV 页池的余量联动，而不是固定常数。</p>\n<p>具体例子：一张高分辨率图像产生大量视觉 token，若整段 prefill 一次跑完，该请求独占 GPU 数个毫秒量级的时间窗，同批的解码请求在这一窗内全部停摆，P99 每 token 延迟出现尖峰。切成若干块后，解码步被插进块间空隙，尖峰被摊平，代价是该请求自身的首 token 延迟略微后移。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-26\">二十六 · 优先级、抢占与 KV 回退的一致性</h3>\n<p>MASSV 的验证阶段有一个容易被忽略的约束：接受前缀写入 KV cache，被拒部分回退到接受长度并由目标分布重采样。抢占若发生在验证步中途，KV 的回退边界必须与重采样点对齐，否则序列状态会落在「已写入但未验证」的中间态，输出与目标模型单独解码不再等价。</p>\n<p>调度器因此要把抢占点限制在投机轮次的边界：一个轮次内草稿生成、并行验证、KV 回退、重采样是原子的，不允许在轮次中间换出。抢占时把整条序列的 KV 连同当前已接受前缀长度一起换出到主机侧或二级池，换入时从该前缀继续草稿。代价是换出粒度变粗，单次换出的数据量比逐 token 抢占大，PCIe 或主机内存带宽成为新的瓶颈；收益是消除了中间态，输出一致性不依赖额外的状态机校验。</p>\n<p>优先级设计上，VLM 服务里至少有两类 SLO：首 token 延迟敏感型（交互式问答）与吞吐敏感型（批量图像描述）。前者要求视觉编码段尽快完成并进入解码，后者可以容忍更长的排队。把视觉编码段作为独立优先级队列，让交互式请求的视觉前向插队到批量请求的 prefill chunk 之间，是压尾延迟的直接手段。代价是批量请求的 prefill 被反复打断，其 chunk 边界变碎，吞吐下降。</p>\n<p>具体例子：一条交互式图文请求到达时，队列里已有多条描述类请求正在 chunked prefill。调度器把交互请求的视觉编码插到下一个 chunk 间隙，其首 token 延迟从排队等待的整段 prefill 时间缩短到一个 chunk 的时间；被插队的描述请求多承受一次 chunk 切换开销，但因其 SLO 宽松，整体不违约。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-27\">二十七 · 分离式预填/解码与草稿模型的落位</h3>\n<p>分离式（disaggregated）预填/解码把 prefill 与 decode 放到不同实例上，中间通过 KV 传输衔接。对 MASSV 而言，这个切分点要重新考虑：草稿模型消费的是目标模型产出的多模态上下文与 KV，若草稿模型与目标模型不在同一实例，每轮投机都要把新增 KV 与视觉表示传过去，传输量随解码轮次线性增长，抵消了投机解码省下的目标前向。</p>\n<p>可行的落位是把草稿模型与目标解码器放在同一节点、同一 NVLink 域内，prefill 实例只负责视觉编码与首段 KV 生产，产出后把 KV 页经 NIXL 传到解码实例。草稿模型在解码实例侧运行，复用本地 KV，不跨节点取视觉表示。这样每轮投机的额外通信只剩草稿模型自身的轻量前向，不引入跨节点同步。</p>\n<p>代价分析：分离式把视觉编码器的显存与解码实例的 KV 池解耦，prefill 实例可以按视觉 token 峰值配置显存，解码实例按并发 KV 长度配置，两边的资源不再互相挤压。但 KV 传输占用 NVLink 带宽，长图文请求的 KV 页数大，传输时间可能盖过 prefill 本身的计算时间。判断标准是 KV 传输时间与解码实例上该请求的首 token 等待时间之比，比值高则分离式不划算。</p>\n<p>具体例子：GB200 NVL72 机架内，prefill 实例与解码实例分处不同 GPU，KV 经 NVLink 5 传输。一条视觉 token 数很多的请求，其 KV 传输耗时与视觉编码前向同量级，此时分离式的收益主要来自资源解耦而非时延；若把草稿模型也放到 prefill 侧，则每轮解码都要回传草稿状态，通信量翻倍，不如同侧部署。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-28\">二十八 · 尾延迟的压法：接受率方差与批内隔离</h3>\n<p>投机解码的尾延迟不来自平均接受率，而来自接受率的方差。MASSV 的蒸馏数据覆盖度决定分布外图文请求的接受率，长尾请求的接受率骤降时，目标模型前向次数回升，该请求的每 token 延迟向无投机基线靠拢，而它占用的批槽位拖累同批其他序列的验证步节奏。</p>\n<p>压尾延迟的第一招是批内隔离：把历史接受率方差大的请求单独成批或降级为无投机路径，不让它污染高接受率批的验证步。第二招是自适应 k：草稿步的候选长度 k 按该请求近期接受前缀长度动态调整，接受率高的请求拉长 k 以放大验证步的有效 token 数，接受率低的请求缩短 k 以减少被拒位置的验证浪费。k 的调整只影响草稿步的轻量前向，不改目标模型行为，因此不破坏输出一致性。</p>\n<div class=\"formula\">$$k^{*} = \\arg\\min_{k} \\left[ \\frac{t_{\\text{draft}}(k) + t_{\\text{verify}}(k)}{a(k)} \\right]$$</div>\n<p>其中 <span>a(k)</span> 为长度 k 的候选序列的期望接受 token 数。分母随 k 增长而饱和，分子随 k 线性增长，最优 k 落在饱和点之前。工程上不必精确求解，用近期接受率的滑动窗口做粗调即可。</p>\n<p>代价是监控开销：接受率、每轮接受前缀长度、目标模型前向次数这三个指标要按请求维度采样，才能识别长尾。采样本身占调度器 CPU 时间，高并发下要限流。第三招是视觉 token 数量的分桶——视觉 token 越多，草稿模型上下文越长，其轻量前向的相对开销越大，投机收益被侵蚀。按视觉 token 数分桶并给大桶请求设置更保守的 k，是把尾延迟压回 SLO 内的直接手段。</p>\n<p>具体例子：一条分布外的图文请求进入高接受率批，其草稿候选大量被拒，验证步的 k 个位置只有 1 个被接受，目标模型为该请求多做了一次近乎全拒的并行前向。若调度器按滑动窗口识别出该请求的接受率低于阈值，将其移出投机批或把 k 降到 1，同批其他序列的验证步节奏恢复，该请求自身也回到可预测的每 token 延迟。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-29\">二十九 · 多模态投机解码的批调度边界：视觉条件如何改写连续批处理与抢占代价</h3>\n<p>把 MASSV 的草稿模型放进连续批处理（continuous batching）时，最先失效的是“按 token 数分桶”这一常规做法。视觉 token 让每条请求的上下文长度在进入解码前就已分化，草稿模型消费的是压缩后的视觉表示加当前前缀，其单步前向的上下文长度随图像 token 数线性增长，而目标模型的验证前向还要并行校验 k 个候选位置。若把图文请求与纯文本请求混在同一批里，批内最长上下文由图像侧决定，短请求被迫等待，尾延迟被拉高。工程上的做法是按视觉 token 数量分桶，把草稿模型的上下文长度控制在窄区间内，再让 chunked prefill 把视觉编码后的首段前向切成固定大小的块，避免一次长前向独占 SM。代价是分桶降低了批的填充率，吞吐让位于尾延迟。</p>\n<p>抢占（preemption）在这里有额外约束：MASSV 的接受前缀写入 KV cache、被拒部分回退到接受长度，回退与重采样的正确性决定输出与目标模型单独解码的等价性。若调度器在验证中途因显存压力抢占一条请求，KV cache 的换出与换入必须落在“接受前缀”这一致点上，而不能落在候选 token 尚未验证的中间态，否则回退长度与重采样位置错位。草稿模型可放在低精度档位腾出 KV cache 空间，这使抢占阈值更宽松，但低精度草稿的分布偏移会压低接受率，形成显存与接受率的对冲。</p>\n<div class=\"formula\">$$\\text{净收益} \\approx \\frac{T_{\\text{target}}}{1 + \\bar{a}\\,k} - T_{\\text{draft}}\\cdot\\frac{k}{1+\\bar{a}\\,k},\\quad \\bar{a}=\\frac{\\text{接受 token 数}}{\\text{候选 token 数}}$$</div>\n<p>分离式预填/解码对 MASSV 是自然契合：视觉编码器只在目标模型侧运行一次，预填节点承担图像前向与首 token 产出，解码节点复用其视觉表示做草稿预测与并行验证，避免重复编码开销摊薄到每轮解码。但跨节点传递压缩后的视觉表示会引入一次带宽代价，NVLink 5 域内可接受，跨域则需把视觉表示与 KV 分片一起做传输预算。失效条件是长尾图文负载：蒸馏数据覆盖度不足时，分布外请求的接受率下降，目标模型前向次数回升，此时分离式部署的传输开销不再被加速比覆盖，尾延迟反而劣于单卡合并部署。判断依据是监控每轮接受前缀长度与目标模型前向次数，在接受率跌破阈值时把该负载切回非投机路径。</p>\n<table class=\"mini\"><thead><tr><th>调度决策</th><th>收益侧</th><th>代价侧</th></tr></thead><tbody><tr><td>按视觉 token 分桶</td><td>压缩批内上下文方差，压尾延迟</td><td>填充率下降，吞吐受损</td></tr><tr><td>chunked prefill</td><td>视觉首段不独占 SM</td><td>块边界增加调度开销</td></tr><tr><td>一致点抢占</td><td>保住输出等价性</td><td>换出粒度粗，显存回收慢</td></tr><tr><td>预填/解码分离</td><td>视觉编码只做一次</td><td>视觉表示跨节点传输</td></tr></tbody></table>\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-30\">三十 · 从单卡草稿到多卡拓扑：切分维度决定通信形态</h3>\n<p>MASSV 的草稿模型本身是轻量的，单卡即可容纳；真正决定部署拓扑的是目标 VLM——视觉编码器与语言解码器合起来往往要跨卡。把目标模型切到多卡时，四种切分各自带来不同的通信原语：TP（张量并行）在每层内部按列/行切权重，每层前向需要两次 All-Reduce；EP（专家并行）在 MoE 层按专家切分，token 到专家的路由是一次 All-to-All；PP（流水并行）按层切段，段间只传激活，通信量最小但引入流水气泡；DP（数据并行）复制权重、切分请求，只在梯度场景需要通信，推理侧几乎零通信，代价是显存不省。草稿模型与目标模型可以同卡共置，也可以分离部署——分离时草稿模型的输出 token 要经一次传输送到目标模型侧做验证，这条链路与目标模型的 TP/EP 通信共享同一张 NVLink 5 网络。</p>\n<p>关键判断是：草稿模型的并行度不必与目标模型一致。草稿模型参数量小，用 DP 复制即可，让每个 DP rank 服务不同请求的草稿阶段；目标模型用 TP/EP 承担验证前向。这样草稿阶段无集合通信，验证阶段才有 All-Reduce/All-to-All，通信被压缩到每轮投机解码的一次验证前向里，而不是每 token 一次。</p>\n<div class=\"formula\">$$T_{\\text{comm}} = \\underbrace{2L \\cdot \\alpha_{\\text{AR}}}_{\\text{TP All-Reduce}} + \\underbrace{N_{\\text{token}} \\cdot \\beta_{\\text{A2A}}}_{\\text{EP All-to-All}} + \\underbrace{S_{\\text{stage}} \\cdot \\gamma_{\\text{PP}}}_{\\text{PP 激活传输}}$$</div>\n<p>其中 L 为层数，α 为单次 All-Reduce 的固定开销与带宽项，β 为每 token 的 All-to-All 代价，γ 为 PP 段间激活传输代价。对 MASSV 而言，一次验证前向要校验 k 个候选位置，这 k 个位置在 TP 下被同一组 All-Reduce 覆盖，通信次数不随 k 线性增长——这是投机解码在多卡上的天然优势：验证的并行性把通信摊薄。代价是显存：k 个候选位置的 KV 需要预留，若草稿模型与目标模型共置，草稿模型的低精度权重能腾出的空间直接决定 k 的上限。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-31\">三十一 · NVLink 5 与 NVSwitch：机柜内带宽的可用面</h3>\n<p>GB200/GB300 NVL72 把 72 个 GPU 通过 NVLink 5 与 NVSwitch 连成单一大域，任意两卡之间是对等带宽，而不是传统 Fat-Tree 下的收敛比。对推理的意义在于：TP 的 All-Reduce 与 EP 的 All-to-All 不再受跨节点 InfiniBand 的时延惩罚，TP 组可以跨 NVLink 域放大到更大规模而不必担心每层两次集合通信的固定开销。但“带宽大”不等于“通信免费”：NVSwitch 是全交叉，所有 rank 同时 All-to-All 时聚合带宽仍会被打满，尤其在 EP 场景下 token 路由不均匀时，热点专家所在链路的拥塞会拖慢整层。</p>\n<p>对 MASSV 的具体含义：视觉编码器只在目标模型侧运行一次，其输出视觉 token 要广播到所有参与验证的 TP rank。视觉 token 数量随图像分辨率增长，这次广播是一次性开销而非每 token 开销，因此在 NVLink 域内可以接受；但如果把视觉编码器放在独立卡上再跨节点传视觉 token，就会把一次性开销变成跨域传输，得不偿失。工程判断是：视觉编码器与语言解码器尽量落在同一 NVLink 域，让视觉 token 的传播走 NVSwitch 而非 IB。</p>\n<p>功耗与带宽是耦合的：NVLink 5 链路在高利用率下功耗显著，机柜级功耗预算会反过来限制可持续的集合通信频率。对长尾图文负载，若 EP 路由不均导致部分链路长期高占用，功耗热点会集中在少数交换机端口上，容量规划时需按最坏路由分布而非平均值估算。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-32\">三十二 · All-Reduce 与 All-to-All 的代价结构</h3>\n<p>All-Reduce 的代价分两段：固定时延（与消息大小无关的握手与同步）和带宽项（与消息大小成正比）。TP 每层两次 All-Reduce，消息大小是 batch×hidden，因此小 batch 时固定时延主导，大 batch 时带宽主导。MASSV 的验证前向 batch 里混着不同请求的 k 个候选位置，batch 维度被候选长度放大，这让 All-Reduce 更容易落入带宽主导区——也就是说，增大 k 会同时增加验证的计算量和通信量，但通信量增长慢于计算量，净收益仍取决于接受率。</p>\n<p>All-to-All 的代价结构不同：它是每 token 一次的消息，消息小、次数多，固定时延与路由开销主导。EP 下 MoE 层的 All-to-All 在解码阶段是每 token 触发，这与投机解码的“一次验证多个 token”形成张力：k 个候选位置各自要过 MoE 路由，All-to-All 次数随 k 增长。若目标模型是 MoE 结构，投机解码在 EP 拓扑下的通信收益会被削弱，需要把 k 控制在路由开销可接受的范围内。</p>\n<table class=\"mini\"><thead><tr><th>原语</th><th>触发频率</th><th>主导项</th><th>MASSV 下的放大因素</th></tr></thead><tbody><tr><td>TP All-Reduce</td><td>每层两次</td><td>小 batch 固定时延 / 大 batch 带宽</td><td>k 个候选位置抬高有效 batch</td></tr><tr><td>EP All-to-All</td><td>每 token 每 MoE 层</td><td>固定时延与路由不均</td><td>k 线性放大次数</td></tr><tr><td>PP 激活传输</td><td>每 microbatch</td><td>带宽</td><td>流水气泡与验证同步</td></tr><tr><td>草稿→目标 token 传输</td><td>每轮投机</td><td>固定时延</td><td>分离部署时每轮一次</td></tr></tbody></table>\n<p>一个具体例子：目标模型为 MoE 的 VLM，EP=8，草稿模型 DP 复制。一轮投机解码中草稿模型在本地生成 k 个候选，送到 8 个 EP rank 做验证；MoE 层对 k 个位置各做一次 All-to-All，共 k 次。若 k 从 4 提到 8，All-to-All 次数翻倍，而验证的计算只增一倍——通信与计算同比例增长，意味着 EP 拓扑下增大 k 不改善通信摊薄，收益纯粹来自接受率。这与 TP 拓扑下“k 增大摊薄 All-Reduce”的结论相反，拓扑选择直接改变投机解码的调参方向。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-33\">三十三 · NIXL 传输：分离式部署的数据面</h3>\n<p>NIXL 面向的是分离式预填/解码与跨进程 KV 传输：它把 KV cache 块从预填实例传到解码实例，绕过主机内存做 GPU 直传。对 MASSV 的直接价值在草稿模型与目标模型分离部署时——草稿模型产出的候选 token 序列、以及验证后被接受前缀对应的 KV 状态，需要在两侧之间流动。候选 token 本身很小（k 个整数），传输代价可忽略；真正的数据面是 KV：若草稿模型与目标模型不共享 KV cache，被接受前缀的 KV 要在目标模型侧重建或搬运，这会把投机解码的收益吃掉。</p>\n<p>因此 MASSV 的分离部署有一个硬约束：草稿模型必须消费目标模型已产生的多模态上下文（含压缩后的视觉表示），且接受前缀直接写入目标模型的 KV cache，被拒部分回退。这意味着 KV 的所有权在目标模型侧，草稿模型只读不写。NIXL 在这里的角色是把目标模型的 KV 块按需暴露给草稿模型侧做条件读取，而不是双向搬运。若做成双向搬运，每轮投机解码都要传一次 KV，传输量随上下文长度增长，长图文负载下 NIXL 带宽会成为瓶颈，抵消草稿模型轻量前向省下的时间。</p>\n<p>工程判断：草稿模型与目标模型同卡共置时，NIXL 不参与关键路径，通信只剩目标模型内部的 TP/EP 集合通信；分离部署时，NIXL 只应承载候选 token 与控制信号，KV 留在目标模型侧。把 KV 搬运放进关键路径是分离式投机解码最常见的性能陷阱。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-34\">三十四 · 通信何时成为瓶颈：三个判据</h3>\n<p>判据一：单轮投机解码的通信时间占比。设一轮中草稿前向时间为 T_draft，验证前向的计算时间为 T_verify，集合通信时间为 T_comm，则一轮的有效时间为 max 或加和取决于是否重叠。当 T_comm &gt; T_verify 时，通信成为瓶颈——这在 TP 度很大、单卡计算被切得很碎时发生，因为每层 All-Reduce 的固定时延不随 TP 度下降。MASSV 的草稿模型轻量，T_draft 小，若目标模型 TP 度过大导致 T_comm 抬高，整轮时间被通信主导，投机解码的收益被稀释。</p>\n<div class=\"formula\">$$\\text{Speedup} \\approx \\frac{T_{\\text{target}}}{T_{\\text{draft}} + T_{\\text{verify}} + T_{\\text{comm}}} \\cdot \\frac{1}{1 - p_{\\text{reject}}}$$</div>\n<p>其中 p_reject 为被拒比例，反映接受率。分母里 T_comm 不随接受率改善而下降，因此接受率再高也有加速上限——这是通信瓶颈的定量表达。</p>\n<p>判据二：EP 路由不均导致的尾延迟。All-to-All 的完成时间由最慢链路决定，热点专家使部分 rank 等待。长尾图文负载下 token 分布偏移，路由更不均，尾延迟拉长。此时增大 batch 不能摊薄，反而加剧拥塞。</p>\n<p>判据三：分离部署的 KV 传输量。若每轮投机解码搬运的 KV 字节数超过 NVLink/NIXL 在该轮时间窗内可传的量，传输就是瓶颈。上下文越长、图像 token 越多，这个判据越容易触发。</p>\n<p>具体例子：一个图像问答负载，视觉 token 数较多，目标模型 TP=8、EP 关闭，草稿模型同卡共置。TP 的 All-Reduce 每层两次，消息大小被 k 个候选位置抬高，落入带宽主导区；由于 k 个位置共享同一次 All-Reduce，通信次数不随 k 增长，T_comm 相对 T_verify 占比下降，通信不是瓶颈，瓶颈回到接受率。换成 EP=8 的 MoE 目标模型，All-to-All 随 k 线性增长，T_comm 占比上升，此时应减小 k 或改用 TP 拓扑承载验证。</p>\n<p>容量规划上，通信瓶颈的识别应落在每轮投机的分解计时上：分别计量草稿前向、验证计算、集合通信、KV 回退与重采样四段。MASSV 的收益取决于接受率提升幅度，而接受率提升只作用于验证前向次数，不作用于通信段——所以部署侧要先把通信段压到非瓶颈，再谈接受率带来的端到端收益。材料未给出接受率与加速比数字，这一分解只能按实际负载实测，不能套用文本域投机解码的经验值。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-35\">三十五 · 草稿模型与目标模型分离部署时的通信边界</h3>\n<p>MASSV 的草稿模型只做轻量前向，显存占用低于目标 VLM，因此天然存在“草稿与目标分离部署”的拓扑选项：草稿模型可放在低精度档位独占一张卡，把省出的显存留给目标模型的 KV cache。一旦分离，每轮投机解码就多出一条跨卡链路——草稿模型需要目标模型已产出的多模态上下文（含压缩后的视觉表示），目标模型则要把 k 个候选位置交给草稿侧再收回验证结果。这条链路的代价与草稿轮次成正比，而草稿轮次又随接受率下降而上升，于是通信开销与接受率形成负反馈：分布外图文请求接受率低，目标模型前向次数增多，跨卡往返次数同步放大。设每轮跨卡传输的上下文与候选张量为 S 字节、单轮解码产生 R 轮草稿，则每 token 的通信量近似为</p>\n<div class=\"formula\">$$B_{\\text{per-token}} \\approx \\frac{S \\cdot R}{L_{\\text{accept}}}, \\quad R \\propto \\frac{1}{L_{\\text{accept}}}$$</div>\n<p>其中 L_accept 为每轮接受前缀长度。接受前缀越长，R 越小，通信被摊薄；反之长尾负载下通信占比抬升，NVLink 5 的带宽优势会被轮次膨胀吃掉。</p>\n<p>切分策略上，草稿模型参数量小，TP 收益有限而 All-Reduce 频次高，更适合 DP 复制以吸收并发；目标模型则按显存与带宽在 TP/PP 间取舍，视觉编码器只在目标侧运行一次，其激活不应跨节点搬运。真正的瓶颈出现在 EP 场景：若目标模型语言解码器采用专家并行，验证阶段的并行前向会触发 All-to-All，此时草稿侧送来的候选 token 必须与专家路由对齐，All-to-All 的尾延迟直接叠加到每轮验证上。工程判断是：把草稿模型与目标模型的同一 TP 组绑定在同一 NVLink 域内，用 NIXL 做 KV 与视觉表示的零拷贝传输，避免候选张量穿越跨节点 InfiniBand；当视觉 token 数量增大导致草稿上下文变长时，优先在草稿侧做上下文分桶而非扩大 TP 度，因为后者增加的是每轮固定 All-Reduce 开销，而前者只影响单次传输体积。</p>\n<table class=\"mini\"><thead><tr><th>拓扑</th><th>主要通信</th><th>失效条件</th></tr></thead><tbody><tr><td>草稿/目标同卡</td><td>无跨卡，仅 KV 回退</td><td>显存不足，KV cache 被挤占</td></tr><tr><td>同 NVLink 域分离</td><td>上下文与候选张量点对点</td><td>接受率低致轮次膨胀</td></tr><tr><td>目标侧 EP</td><td>验证前向 All-to-All</td><td>专家路由尾延迟叠加每轮验证</td></tr></tbody></table>\n<p>KV cache 回退是另一处隐性通信代价：被拒部分回退到接受长度后，草稿侧持有的上下文副本必须与目标侧 KV 保持一致，否则下一轮草稿预测基于过期前缀，接受率进一步下滑。回退与重采样的一致性因此不只是正确性问题，也是通信量问题——不一致会诱发额外重传。材料未给出并行拓扑与硬件档位，部署时需按实际图文负载实测接受率与跨卡往返占比，再决定草稿模型是否值得独立成卡。</p>\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-36\">三十六 · 精度塌陷：接受率掉下去时，先分清是分布问题还是数值问题</h3>\n<p>MASSV 的收益全部押在“草稿分布与目标分布在视觉条件下对齐”这一条上，因此精度塌陷的第一现场不是输出错字，而是<strong>接受率与每轮接受前缀长度同时下滑</strong>。诊断时必须把两类原因拆开：一类是分布失配——草稿模型没见过这类图像条件，或蒸馏数据覆盖不到该负载；另一类是数值退化——草稿模型被放到低精度档位后，其 top-k 候选与目标模型验证时的比较出现系统性偏移。前者表现为“某些请求形态整体接受率低”，后者表现为“同一请求在不同精度档位下接受前缀长度不同”。定位手段是给每个请求记录三元组：视觉 token 数、草稿模型精度档位、本轮接受前缀长度；按视觉 token 数分桶后看接受率曲线，若曲线在某个桶上断崖式下跌而精度档位未变，指向蒸馏数据覆盖度不足；若同一桶在不同档位间差异显著，指向数值问题。工程代价上，接受率每下降一档，目标模型前向次数按轮数线性上升，端到端延迟随之抬升，而视觉编码段不变，于是延迟结构从“解码主导”退化为“验证主导”。一个具体例子：图像描述类负载的视觉 token 数远高于短问答，若蒸馏数据以问答为主，描述类请求的草稿上下文变长、接受率下降，表现为长图请求的每 token 延迟明显高于短图请求——这不是硬件问题，是数据配方问题。</p>\n<div class=\"formula\">$$\\text{speedup} \\approx \\frac{1}{1 - \\alpha + \\alpha/k},\\quad \\alpha=\\text{接受率},\\ k=\\text{每轮草稿长度}$$</div>\n<p>该式给出诊断的量化锚点：α 下滑时加速比按上式收缩，k 越大对 α 越敏感。因此监控面板上应把 α 与 k 分开呈现，而不是只报一个“加速比”。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-37\">三十七 · OOM：草稿模型省下的显存，会被视觉 token 与回退缓冲吃掉</h3>\n<p>MASSV 的结构性优势是草稿模型只做轻量前向、显存占用低于目标模型，可放低精度档位腾出 KV cache 空间。但 OOM 在 VLM 投机解码里往往不来自权重，而来自三处动态占用：视觉 token 拼接后的上下文长度、草稿模型一次预测 k 个候选所需的临时激活、以及验证被拒后 KV cache 回退时保留的“待重采样”缓冲。视觉编码器只在目标模型侧运行一次，其视觉表示被草稿模型复用，这省掉了重复编码，但视觉 token 本身仍进入草稿模型上下文——图像分辨率越高、token 越多，草稿侧上下文越长，k 步预测的激活随 k 线性增长。定位方法是把显存占用按“权重 / KV cache / 草稿激活 / 回退缓冲”四段打点，观察 OOM 前哪一段在爬升；若草稿激活段随 k 上升而爆，应下调 k 或对草稿模型做更激进的低精度；若 KV cache 段随并发上升而爆，应改批调度侧的视觉 token 分桶策略。代价上，k 下调直接削弱投机解码的摊薄效应，目标模型前向次数上升；而单纯缩并发会牺牲吞吐。一个具体例子：长图描述请求与短问答混批时，批内最长上下文由长图决定，短请求被迫按长请求的 KV 预留，OOM 先于吞吐瓶颈出现——此时正确动作是按视觉 token 数分桶而非降 k。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-38\">三十八 · 批抖动：接受前缀长度不一致，把批内同步拖成尾延迟</h3>\n<p>投机解码的验证阶段是目标模型对 k 个候选位置做一次并行前向，接受最长一致前缀后被拒位置重采样。问题在于<strong>每个请求每轮接受的前缀长度不同</strong>：同一批里有的请求一轮接受 k 个 token，有的只接受 1 个，下一轮草稿长度与 KV 回退位置随之分叉。批调度若按固定步长推进，短接受请求会空转等待长接受请求，批内有效 token 产出率被最慢请求钉住，形成批抖动。诊断指标是“批内接受前缀长度的方差”与“每轮批有效 token 数 / 批名义 token 数”，前者高说明请求形态混杂，后者低说明同步开销吃掉收益。定位后有两种工程动作：一是按接受前缀长度动态重组批，把接受行为相近的请求聚到一起，代价是重组本身的调度开销与 KV 搬移；二是对草稿长度 k 做请求级自适应，对历史接受率低的请求缩短 k，减少无效验证位。代价上，动态重组提升吞吐但增加调度复杂度与显存碎片；k 自适应降低尾延迟但需要维护每请求的接受率滑动窗口。一个具体例子：图文问答与图像描述混跑时，描述类请求因上下文长、接受率低而每轮只推进一两个 token，问答类请求一轮吃满 k，混批后批名义 token 数虚高、实际产出被描述类拖住——这正是按负载形态分桶的直接理由。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-39\">三十九 · 尾延迟：视觉编码段与解码段必须分开计量</h3>\n<p>VLM 推理延迟由视觉编码器前向与自回归解码两段构成，MASSV 把视觉编码开销摊薄到整段解码，但摊薄的前提是解码轮数足够多。对短输出请求（如单轮短问答），解码轮数少，视觉编码段在总延迟中占比高，投机解码省下的目标模型前向次数不足以抵消首 token 前的编码等待，尾延迟由编码段主导；对长输出请求，解码段主导，接受率成为尾延迟的主变量。因此 SLO 必须把首 token 延迟与每 token 延迟分开计量，且首 token 延迟里要再拆出视觉编码耗时。诊断尾延迟的抓手是 P99 请求的耗时构成：若 P99 落在视觉编码段，说明长图或高分辨率请求在排队等编码器，应做视觉 token 数分桶与编码段并发隔离；若 P99 落在解码段且伴随低接受前缀长度，说明该请求落在蒸馏数据覆盖之外，草稿模型退化成了“每轮只接受一位”的近似无加速状态。代价上，编码段隔离会降低编码器利用率，但能把尾延迟从编码排队中摘出来；对分布外请求降级为普通解码（绕过草稿）可保住尾延迟上界，代价是放弃该请求的加速收益。一个具体例子：长尾图文负载中偶发的高分辨率图像使视觉 token 数激增，该请求的编码段耗时远超同批其他请求，P99 被单条请求拉高——监控上应把视觉 token 数作为尾延迟的第一维度标签。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-40\">四十 · 静默降级：输出仍“对”，但等价性与加速都已失守</h3>\n<p>最危险的失败模式不是报错，而是系统仍在产出、指标仍绿，但两条隐式契约已被破坏。第一条是<strong>输出等价性</strong>：验证阶段接受前缀写入 KV cache、被拒部分回退到接受长度后由目标分布重采样，回退位置与重采样的一致性决定最终序列是否与目标模型单独解码一致。若回退长度算错一位、或重采样用了草稿分布而非目标分布，输出会缓慢偏离目标分布，且不触发任何异常——这是静默降级。第二条是<strong>加速有效性</strong>：草稿模型在多模态自适应缺失或蒸馏覆盖不足时，接受率退到接近零，系统仍每轮跑一次草稿前向加一次目标验证前向，延迟反而高于不做投机解码，但因为没有错误输出，监控不会报警。诊断这两条需要独立探针：等价性探针定期抽样请求，用目标模型单独解码重跑并逐 token 比对；有效性探针记录“每轮目标模型前向次数 / 产出 token 数”，该比值逼近 1 说明投机解码已无收益，应自动摘除草稿路径。代价上，等价性探针消耗额外目标模型算力，只宜抽样；有效性探针几乎零成本，应常驻。一个具体例子：某批请求的草稿模型因视觉条件输入未正确拼接而退化为纯文本草稿，接受率极低，但输出经目标模型验证后仍正确，面板上只有“每 token 延迟偏高”这一个弱信号——把有效性比值做成告警阈值，才能把这种静默降级变成显式事件。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-41\">四十一 · 回滚：按失败模式分层，而不是整体回退到无投机解码</h3>\n<p>回滚粒度决定故障代价。整体回退到“目标模型单独解码”最安全，但放弃了全部加速收益，且在大促或高并发时直接把容量打回基线。分层回滚更合理：第一层是<strong>请求级降级</strong>，对接受率滑动窗口低于阈值的请求或视觉 token 数超出蒸馏覆盖范围的请求，绕过草稿路径直接走目标模型解码，保住尾延迟上界；第二层是<strong>精度档位回滚</strong>，草稿模型从低精度档位升回较高精度，代价是显存占用上升、可能挤压 KV cache，需同步下调并发或 k；第三层是<strong>k 回滚</strong>，把每轮草稿长度降到 1–2，牺牲摊薄效应换验证稳定性；第四层才是全局摘除草稿模型。触发条件应绑定具体指标而非主观判断：接受率跌破阈值触发第一层，同请求在不同档位下接受前缀长度差异显著触发第二层，批内接受前缀长度方差过高触发第三层。回滚动作必须与 KV cache 回退逻辑对齐——切换路径时在途请求的 KV 状态需按接受前缀截断后交接，否则等价性契约在回滚瞬间被破坏。一个具体例子：蒸馏数据未覆盖的图文负载在流量中占比上升，接受率整体下滑，此时正确动作是把这批请求按视觉 token 数与负载类型打标后走请求级降级，而不是把整个服务摘掉草稿模型——后者会让本可加速的问答类请求一并失去收益。回滚的工程判断落在“按失败模式分层、按指标自动触发、切换时保住 KV 一致性”这三条上，任何一条缺失都会把一次局部退化放大成全局容量事件。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-42\">四十二 · 多模态投机解码的失效边界：从接受率塌陷到静默降级</h3>\n\n<p>MASSV 的收益完全绑定在一个量上：草稿模型在视觉条件下的接受率。这个量一旦偏离训练分布，系统不会报错，只会变慢——这是最危险的一类失效。文本域草稿模型迁移到 VLM 时，图像 token 改变了上下文分布，草稿模型未见过的视觉条件使其预测偏离目标分布，接受率下降直接转化为目标模型前向次数的上升。设每轮草稿预测 k 个 token、接受前缀长度为 a，则目标模型前向次数约为 N/(a+1)（N 为总输出 token 数），端到端解码延迟近似正比于该次数。当 a 从训练分布内的水平跌到接近 0，投机解码退化为“每轮只接受一个 token 再重采样”，草稿前向与验证前向的开销全部变成纯附加成本，延迟反而高于不用投机解码的基线。诊断上应把“每轮接受前缀长度”与“目标模型前向次数/输出 token”作为一等指标，而不是只看吞吐；前者掉、后者涨，就是精度塌陷的早期信号。</p>\n\n<p>第二类失效是显存与批抖动。草稿模型虽只做轻量前向、可放低精度档位，但它与目标模型共享同一张卡的显存预算，视觉 token 数量增长会同时抬高两侧的上下文长度：目标模型侧 KV cache 随图像 token 与生成长度增长，草稿模型侧上下文随视觉表示与已生成前缀增长。长尾图文负载（高分辨率、多图、长描述）进入时，单请求显存需求突增，连续批处理被迫拆分批次或拒绝新请求，表现为批大小抖动与尾延迟抬升。工程上应按视觉 token 数量分桶，把草稿模型上下文长度纳入调度约束，并对 KV cache 回退路径做容量核算——回退到接受前缀长度意味着被拒位置的 KV 必须可丢弃且可重建，若实现为原地覆盖而非版本化写入，回退与重采样的一致性就会被破坏，输出不再等价于目标模型单独解码，这是静默降级的第三种形态：结果看似正常，实则偏离了“目标模型冻结、输出分布不变”的前提。</p>\n\n<p>监控与回滚应围绕三个可观测面组织：接受率与每轮前缀长度（草稿侧）、目标模型前向次数与 KV 回退次数（验证侧）、视觉编码段与解码段的分段延迟（SLO 侧）。下表给出失效模式到定位手段的映射，其中“静默降级”一栏的关键是设置输出一致性抽检——用同一图文请求分别走投机路径与目标模型单独解码路径，逐 token 比对，任何不一致都触发回滚到纯目标模型解码。回滚粒度应做到按请求形态（图像问答 / 描述类）与按视觉 token 分桶独立切换，避免全局关闭投机解码把正常负载的收益一并丢掉。</p>\n\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>接受率塌陷</td><td>每轮前缀长度下降、前向次数上升</td><td>按负载形态切分接受率</td><td>该形态切回目标模型解码</td></tr><tr><td>OOM / 批抖动</td><td>批大小波动、尾延迟抬升</td><td>按视觉 token 分桶核算显存</td><td>收紧桶上限、降草稿精度档</td></tr><tr><td>静默降级</td><td>输出与基线不一致</td><td>双路径逐 token 抽检</td><td>禁用该桶的回退路径</td></tr></tbody></table>\n\n<p>边界判断的落脚点是蒸馏数据覆盖度：草稿模型的监督来自目标 VLM 在图文样本上的自采样分布，覆盖不到的长尾请求上接受率必然下降，而这一下降不会以错误形式暴露，只以延迟形式暴露。因此容量规划不能按平均接受率折算，必须按分桶后的最差接受率估算目标模型前向次数上限，并预留草稿模型低精度档位下的显存余量给 KV 回退峰值。</p>\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-43\">四十三 · 口径先于数字：这份材料能读出什么、不能读出什么</h3>\n<p>MASSV 这一篇的基准信息是残缺的：材料明确未给出接受率、加速比、吞吐、数据集名称、基线名称与硬件档位。这意味着任何“MASSV 在 B200 上把 VLM 解码提速 N 倍”的说法都不是从这篇材料里读出来的。工程读者拿到这种材料，正确的读法是把它当成<strong>机制可验证、数字待实测</strong>的一类工作：先确认它的度量对象是什么，再判断哪些量在自家负载上必须自己补测。本文后续所有关于代价的讨论都落在定性层面，凡出现具体数值的地方，只使用材料中已有的 k（候选 token 数）与“一次并行前向”这类结构性事实。</p>\n<p>需要区分三类量。第一类是<strong>方法内生的量</strong>：接受率 α、每轮接受前缀长度、目标模型前向次数。这三个量由草稿模型与目标分布在视觉条件下的对齐程度决定，是 MASSV 直接作用的对象。第二类是<strong>系统外生的量</strong>：TTFT、TPOT、吞吐、显存占用、功耗，它们由硬件档位、batch、并发、精度档位共同决定，MASSV 只通过“减少目标模型前向次数”间接影响。第三类是<strong>不可比的量</strong>：不同视觉 token 数、不同图像分辨率、不同 batch 下报出的加速比，彼此之间没有换算关系。把第一类当成第二类的证明，是这类论文最常见的误读方式。</p>\n<div class=\"formula\">$$\\text{Speedup} = \\frac{T_{\\text{target}}}{T_{\\text{draft}} + T_{\\text{verify}}/\\alpha_{\\text{eff}}}$$</div>\n<p>这个式子只用来表达结构：分母里草稿前向与验证前向是相加关系，接受率越低，验证项被除得越大，加速比趋近于 1 甚至因草稿开销而小于 1。材料没有给出 α 的实测值，所以这个式子在本文里是<strong>口径工具</strong>而非结论——它告诉你该测哪三个量，而不是告诉你答案是多少。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-44\">四十四 · 硬件档位：Blackwell 上哪些量随档位变、哪些不变</h3>\n<p>材料未给硬件档位，因此不能声称 MASSV 在 SM100 或 SM103 上有特定表现。但可以把 Blackwell 部署中与 MASSV 相关的量按“是否随档位缩放”分类，这决定了你复现时该固定什么、该扫什么。随档位缩放的是：目标模型单次前向的绝对时延（受算力与显存带宽共同约束）、KV cache 可容纳的并发序列数（受 HBM 容量约束）、以及低精度档位下草稿模型可用的显存余量。不随档位缩放的是：接受率 α 本身——它由草稿模型与目标分布的统计关系决定，换卡不改变分布对齐程度，只改变每次前向的代价。</p>\n<p>这个区分有直接工程后果。若在 B200 单卡上测得某 α，换到 GB200 NVL72 机架做分离式部署时，α 不变，但验证前向的代价因目标模型被切分到多卡而改变，端到端加速比会漂移。反过来，若把草稿模型放到低精度档位（材料明确这是可行路径），α 可能因数值精度下降而轻微退化，而草稿前向的时延与显存占用同时下降——这是一个需要实测权衡的点，材料没有给出退化幅度。</p>\n<p>具体例子：在同一目标 VLM 上，把草稿模型从目标模型同精度改为低精度档位，显存侧的直接收益是腾出的空间可折算为更多 KV cache 页，从而抬高并发上限；代价侧是草稿分布与目标分布的偏差可能压低 α。由于 α 不随硬件档位变，这个权衡的结论在 B200 与 GB300 上应当一致，差异只体现在绝对时延上——这正是“先测 α、再谈加速比”的理由。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-45\">四十五 · batch 与并发：为什么 MASSV 的收益在小 batch 下才成立</h3>\n<p>投机解码的收益结构对大 batch 不友好。目标模型在 decode 阶段是访存受限的，batch 增大后单次前向的边际成本被摊薄，验证 k 个候选位置的那次并行前向与验证 1 个 token 的前向在时延上差距很小——也就是说，投机解码省下的是<strong>前向次数</strong>，而大 batch 下每次前向本来就已被摊薄，省次数的价值下降。材料未给 batch 与并发，但从机制上可以判断：MASSV 的净收益在低并发、延迟敏感的图文请求上最明显，在高并发吞吐取向下会被稀释。</p>\n<p>并发侧还有一层与视觉 token 数耦合的效应。材料指出视觉 token 数量增长会抬高草稿模型上下文开销，抵消部分收益。草稿模型消费的是目标模型已产生的多模态上下文（含压缩后的视觉表示），因此草稿序列的有效长度 = 视觉 token 数 + 已生成文本长度。并发升高时，若不做按视觉 token 数分桶（材料明确这是部署侧需要做的事），长短不一的图文请求混批会让草稿模型侧的上下文长度方差变大，短请求被长请求拖慢，长请求的草稿开销又吃掉自身收益。</p>\n<p>具体例子：图像问答类负载中，单图请求的视觉 token 数远小于多图或高分辨率描述类请求。若两类请求同批，草稿模型对每个序列都要处理各自的视觉条件，批内最长序列决定该批的草稿前向时延下界；把两类分桶后，短请求批的 α 与每轮接受前缀长度不受长请求影响，TPOT 分布更集中。这是调度层的动作，与 MASSV 的模型侧改动正交，但决定了它的收益能否兑现。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-46\">四十六 · 指标口径：TTFT、TPOT、吞吐、显存、功耗各自测什么</h3>\n<p>材料明确 SLO 关注首 token 延迟与每 token 延迟，且视觉编码段与解码段分别计量。这个“分段计量”是读 MASSV 数字的关键口径。视觉编码器只在目标模型侧运行一次，草稿模型复用其视觉表示，因此 TTFT 的主体是视觉编码前向加目标模型首 token 前向，MASSV 对 TTFT 的贡献接近于零——它加速的是首 token 之后的解码段。任何把 TTFT 改善归因于 MASSV 的表述都与机制不符。</p>\n<p>TPOT 才是 MASSV 的作用面。每一轮解码的时延构成为：草稿模型轻量前向（k 步）+ 目标模型一次并行验证前向 + KV cache 回退与重采样的簿记开销。接受前缀越长，单位时间内推进的 token 越多，TPOT 越低。但注意簿记开销：材料强调回退与重采样的正确性决定输出一致性，这条在性能侧同样成立——回退需要把 KV cache 截断到接受长度，若实现上每次回退都触发一次页表重写或拷贝，簿记开销会侵蚀掉验证前向省下的时间。这是工程实现细节，材料未给数据，但它是 TPOT 口径下必须单独打点的项。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>MASSV 是否直接作用</th><th>口径要点</th></tr></thead><tbody><tr><td>TTFT</td><td>否（视觉编码段不变）</td><td>视觉编码与首 token 前向分开计时</td></tr><tr><td>TPOT</td><td>是（减少目标前向次数）</td><td>含草稿前向、验证前向、KV 回退簿记三项</td></tr><tr><td>吞吐</td><td>间接（高并发下被稀释）</td><td>需标注 batch 与视觉 token 分桶策略</td></tr><tr><td>显存</td><td>间接（草稿模型可低精度）</td><td>草稿权重 + 目标权重 + KV cache 三者分列</td></tr><tr><td>功耗</td><td>间接（前向次数减少）</td><td>按每千 token 能耗计，非瞬时功率</td></tr></tbody></table>\n<p>显存口径要分三块列：草稿模型权重、目标模型权重、KV cache。材料指出草稿模型显存占用低于目标模型，可放低精度档位腾出 KV cache 空间——这意味着显存收益不是“总量下降”，而是“结构重分配”：草稿权重占比小，腾出的空间转化为并发上限。功耗口径同理，MASSV 减少的是目标模型前向次数，能耗应按每千输出 token 计量而非瞬时功率，否则视觉编码段的一次性开销会污染读数。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-47\">四十七 · 哪些提升不可比：四类典型误配</h3>\n<p>第一类误配是<strong>视觉 token 数不同</strong>。材料指出视觉 token 数量增长抬高草稿上下文开销，因此两个报出的加速比若对应的图像分辨率或 token 压缩率不同，不可直接比较。第二类是<strong>负载形态不同</strong>：材料给出的蒸馏数据覆盖图像问答与图像描述两类，这两类负载的生成长度分布差异大，描述类长生成让投机解码有更多轮次摊薄视觉编码开销，问答类短生成则相反，加速比天然更低。</p>\n<p>第三类是<strong>基线选择</strong>。材料未给基线名称，但机制上存在三种合理基线：目标模型单独解码（无投机）、文本域草稿模型的投机解码、以及视觉 token 压缩后的目标模型解码。MASSV 相对第一种的加速比包含全部投机收益，相对第二种才隔离出“多模态自适应 + 自数据蒸馏”的增量，相对第三种则混杂了压缩与投机的交互。三者不可互换，读数字时必须问清分母是谁。</p>\n<p>第四类是<strong>一致性口径</strong>。材料明确目标模型冻结、只训练草稿模型，最终输出分布与目标模型单独解码一致。这条是正确性声明而非性能声明，但它影响可比性：若某实现为追求 α 而在验证阶段放宽接受判据（例如按 top-1 匹配而非分布比较），α 会虚高而输出等价性被破坏，此时报出的加速比与 MASSV 不在同一口径下。材料中的蒸馏损失用接受指示函数加权，说明训练目标与验证判据是同一套接受语义，这一点在复现时必须对齐。</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\text{distill}} = -\\sum_{t} \\log p_{\\text{target}}(x_t \\mid x_{&lt;t}, v) \\cdot \\mathbb{1}\\left[\\text{accept}(x_t)\\right]$$</div>\n<p>这个式子里的指示函数是口径锚点：训练时只对会被接受的位置计损失，意味着草稿模型被优化去命中验证器会放行的 token。若复现时改了接受判据而不改训练目标，α 的读数就失去意义。这是“数字怎么读”的最具体一条——先核对训练与验证是否共用接受语义，再谈加速比。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-48\">四十八 · 复现时的最小实测集：把缺失的数字补在哪</h3>\n<p>给定材料的信息缺口，复现 MASSV 时应补测的最小集合是四项，按依赖顺序排列。其一，<strong>接受率 α 与每轮接受前缀长度</strong>，按视觉 token 数分桶统计，因为这是唯一不随硬件档位变的量，也是判断方法是否生效的第一道闸。其二，<strong>目标模型前向次数</strong>，材料明确这是监控指标之一，它直接对应 TPOT 的分子项，且与 α 互为印证——α 上升而每轮前向次数不降，说明簿记开销吃掉了收益。</p>\n<p>其三，<strong>KV cache 回退的正确性与开销</strong>。材料把“回退与重采样的一致性”列为失败模式，工程上要同时测两件事：回退后继续解码的输出是否与目标模型单独解码逐 token 一致（正确性），以及每次回退的簿记时延占该轮 TPOT 的比例（开销）。其四，<strong>长尾图文负载的 α 退化幅度</strong>。材料指出蒸馏数据覆盖度决定分布外请求的接受率，长尾负载下 α 下降会抵消收益；这一项无法从平均 α 读出，必须单独构造分布外样本集。</p>\n<p>具体例子：构造一组视觉 token 数处于分布上沿的图文请求（多图或高分辨率），与蒸馏数据覆盖的常规问答请求对比 α。若前者 α 明显低于后者，则部署时应把这类请求路由到非投机路径，或在调度层按视觉 token 数分桶后对长桶关闭草稿阶段——这是一个纯工程判断，材料没有给出阈值，阈值只能由自家负载的 SLO 反推：当某桶的 TPOT 在开启投机后不降反升，该桶就该退出投机路径。</p>\n<p>最后落在机制上：MASSV 的收益链条是“视觉条件对齐 → α 上升 → 目标前向次数下降 → TPOT 下降”，链条上任何一环没有单独打点，端到端数字都无法归因。材料未给数字这件事本身不是缺陷，它把度量责任交回给部署方——在 Blackwell 上跑这套方法，先测 α 与回退开销，再谈加速比，顺序不能颠倒。</p>\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-49\">四十九 · 迁移到非 MASSV 目标模型时，草稿侧的三个耦合点</h3>\n<p>把 MASSV 的草稿构造方式搬到另一个 VLM 上，真正要改的不是训练脚本，而是草稿模型与目标模型之间的三处接口。第一处是视觉表示的注入形式：MASSV 的草稿模型消费的是目标模型视觉编码器产出的、已投影到语言嵌入空间的视觉 token，而不是原始像素。换目标模型时，视觉编码器的 token 数量、投影维度、是否做 token 压缩都变了，草稿侧的多模态自适应层必须按新的视觉表示宽度重建，否则视觉条件在草稿侧被截断或补齐成噪声。第二处是上下文窗口的切分：草稿模型接收的是“压缩后的视觉表示 + 已生成前缀”，目标模型的 KV cache 布局（层数、头数、是否 GQA、是否分页）决定了草稿侧能复用多少前缀状态。第三处是验证语义：接受判据是逐位比较草稿分布与目标分布，这要求草稿模型的词表与目标模型严格同构；换模型时若词表有增删，接受判据必须改成对共同子词表比较，否则接受率会被系统性低估。</p>\n<p>代价落在显存与带宽上。草稿模型虽轻，但其多模态自适应层引入的视觉条件投影会额外占用一份激活与权重；在目标模型已经吃满 HBM 的部署里，草稿模型只能挤在剩余显存中，且必须与 KV cache 竞争。以 NVL72 单机架内多副本部署为例，若每个副本都带一份草稿模型，草稿权重与视觉投影层的常驻占用会按副本数线性叠加，直接压缩可分配给 KV cache 的页数，进而压低最大并发。工程判断是：迁移时先算“草稿权重 + 视觉投影 + 每副本最小 KV 页”三者之和是否落在单卡余量内，再决定草稿与目标同卡还是分离部署；同卡省通信但抢显存，分离省显存但每轮验证多一次跨卡候选传输。</p>\n<div class=\"formula\">$$\\text{草稿侧可行域}:\\; W_{\\text{draft}} + W_{\\text{vis-proj}} + P_{\\min}\\cdot S_{\\text{kv}} \\le \\text{HBM}_{\\text{free}}$$</div>\n<p>其中 $P_{\\min}$ 是维持目标 SLO 所需的最小 KV 页数，$S_{\\text{kv}}$ 是单页字节数。这个不等式比任何“草稿模型很轻”的定性说法都更能决定迁移成败：当 $P_{\\min}$ 随并发上升时，草稿侧可行域迅速收缩，此时把草稿放到低精度档位不只是省显存，更是把可行域从空集拉回非空。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-50\">五十 · 换领域时，蒸馏数据的覆盖度就是接受率的上界</h3>\n<p>MASSV 的监督信号来自目标 VLM 在图文输入上的自采样分布，这意味着草稿模型学到的是“目标模型在被采样到的那类图文负载上的行为”。换领域时，第一件要评估的事不是草稿结构，而是自蒸馏数据是否覆盖了新领域的请求形态。图像问答与图像描述两类负载的 token 分布差异极大：描述类负载的下一 token 高度依赖视觉细节，问答类负载则更依赖指令与视觉的联合条件。若新领域是文档理解、图表推理或视频帧序列，视觉 token 的密度与语义粒度都变了，草稿模型在旧数据上训出的视觉条件映射会失配。</p>\n<p>机制上，蒸馏损失只对被接受的位置加权：</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\text{distill}} = -\\sum_{t} \\log p_{\\text{target}}(x_t \\mid x_{&lt;t}, v) \\cdot \\mathbb{1}\\left[\\text{accept}(x_t)\\right]$$</div>\n<p>这个指示函数意味着训练信号本身是被接受率筛选过的：在旧领域接受率高的位置贡献大，在新领域本就容易失配的位置贡献小甚至为零。于是草稿模型会自我强化已有领域的对齐，而对新领域的长尾分布缺乏梯度。迁移到新领域时若不重新采样蒸馏数据，接受率的上界就被旧数据的覆盖度锁死。代价体现在目标模型前向次数上：接受率每下降一档，每生成一个 token 所需的目标前向次数上升，端到端延迟随之抬升，而视觉编码段的固定开销无法被摊薄。</p>\n<p>具体例子：把一套在自然图像问答上蒸馏出的草稿模型直接用于密集文字截图问答，视觉 token 数量上升、文字区域的 token 语义更接近语言先验，草稿模型容易在数字与符号位置给出与目标分布偏离的候选，验证阶段这些位置被拒，接受前缀变短，KV cache 回退更频繁。此时正确做法不是调草稿温度，而是用目标模型在新领域样本上重新自采样，把新领域的视觉条件分布补进蒸馏集。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-51\">五十一 · 规模上限：视觉 token 增长如何吃掉投机收益</h3>\n<p>投机解码的净收益取决于“草稿开销 + 验证开销”与“被省掉的目标前向”之间的差额。MASSV 把视觉编码固定在目标侧只跑一次，这一点在高分辨率输入下尤其关键，但它没有消除另一个规模项：草稿模型的上下文长度随视觉 token 数线性增长。草稿模型每轮要在“视觉表示 + 前缀”上做轻量前向，视觉 token 越多，草稿侧每轮的注意力计算与激活读写越大，草稿开销从可忽略变为可观。</p>\n<p>设每轮草稿预测 $k$ 个候选、平均接受前缀长度为 $\\bar{a}$，则每个被接受 token 摊销的目标前向次数约为 $1/\\bar{a}$，而草稿侧每轮的代价正比于 $L_{\\text{vis}} + L_{\\text{prefix}}$。当 $L_{\\text{vis}}$ 增大时，草稿侧代价上升而 $\\bar{a}$ 未必上升，净收益被双向挤压。规模上限由此浮现：存在一个视觉 token 数阈值，超过它之后草稿开销的增量超过验证节省的增量，投机解码从加速变为拖累。这个阈值不是常数，它随目标模型的验证并行度、草稿精度档位与批内视觉长度方差变化。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>对接受率</th><th>对草稿开销</th><th>净效应判断</th></tr></thead><tbody><tr><td>视觉 token 数上升</td><td>条件更丰富，可能升</td><td>上下文变长，线性升</td><td>过阈值后转负</td></tr><tr><td>批内视觉长度方差大</td><td>分桶不当则降</td><td>按最长桶对齐，浪费</td><td>需按 token 数分桶</td></tr><tr><td>草稿精度档位下调</td><td>略降</td><td>显存与带宽降</td><td>可行域扩大，通常正</td></tr><tr><td>目标验证并行度提高</td><td>不变</td><td>验证一次覆盖更多候选</td><td>摊薄验证开销</td></tr></tbody></table>\n<p>工程判断：迁移到高分辨率或多帧输入场景时，先测“草稿侧单轮前向时间 / 目标侧单次验证前向时间”这个比值。比值小说明草稿足够轻，规模上限高；比值接近 1 说明草稿已不再是“轻量”，此时应优先做视觉 token 压缩或按视觉长度分桶，而不是继续加大 $k$。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-52\">五十二 · 不适用的场景：三类请求不该套这套方案</h3>\n<p>第一类是首 token 延迟主导的请求。MASSV 的收益全部落在解码段，视觉编码与目标模型首次前向的固定开销不受草稿模型影响。当请求输出很短（例如单轮分类式问答、短描述），解码段占比低，草稿模型带来的接受率提升无法覆盖其常驻显存与初始化成本。此类负载的正确优化对象是视觉编码器前向与预填并行，而不是投机解码。</p>\n<p>第二类是输出分布本身高度不确定的请求。投机解码的接受率依赖草稿分布与目标分布的接近程度，而自蒸馏只能逼近目标模型在已采样数据上的行为。开放式长文生成、多轮对话中话题漂移大的请求，目标分布随前缀快速变化，草稿模型的多模态自适应层难以在每轮维持对齐，接受前缀变短，验证轮次增多。这类负载下投机解码仍能保证输出一致，但加速比不稳定，容量规划不能按平均接受率做。</p>\n<p>第三类是目标模型频繁切换或版本迭代的服务。草稿模型与目标模型是绑定关系：目标模型权重冻结是 MASSV 的前提，一旦目标模型升级，蒸馏数据与草稿对齐同时失效，必须重新自采样与重训。若服务侧按多模型路由、按请求切模型版本，草稿模型的数量与显存占用按模型数放大，维护成本超过收益。判断标准很直接：目标模型版本在草稿生命周期内是否稳定；不稳定则这套方案不适合作为默认路径。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-53\">五十三 · 迁移检查清单：把判断落到可测的量上</h3>\n<p>迁移一套 MASSV 式方案，需要按顺序验证四件事，每件都对应一个可测的量而非口号。其一，视觉条件接口是否对齐：检查草稿侧视觉投影维度与目标视觉 token 宽度是否一致，不一致则重建自适应层，测重建前后在固定图文样本上的接受前缀长度。其二，蒸馏覆盖度是否匹配新领域：用目标模型在新领域样本上自采样，比较新旧蒸馏集上草稿模型的平均接受前缀长度，若新领域显著更低则必须补数据。其三，草稿开销占比是否越界：测草稿单轮前向时间与目标单次验证前向时间之比，结合视觉 token 数分布画出随长度变化的曲线，找出净收益转负的拐点。其四，回退一致性是否守住：在接受前缀写入 KV cache、被拒位置重采样的路径上做逐 token 比对，确认输出与目标模型单独解码逐位一致；这是这套方案唯一不能妥协的正确性约束，任何为提速而放宽回退语义的改动都会破坏等价性。</p>\n<p>这四项里，前两项决定接受率的上界，第三项决定规模上限，第四项决定方案是否还能被称为“不改变输出分布”。迁移的工程判断可以压缩成一句：当且仅当草稿侧可行域非空、蒸馏覆盖度匹配目标领域、草稿开销占比低于验证节省、回退路径逐位一致时，这套方案才值得在目标模型上启用；任一条件不满足，应先修该条件，而不是调 $k$ 或换精度档位来掩盖它。</p>\n\n<h3 id=\"paper-massv-multimodal-adaptation-and-self-2025-sec-54\">五十四 · 迁移边界：草稿对齐在什么条件下失效</h3>\n<p>把 MASSV 搬到另一个 VLM 上，最先要改的不是草稿模型结构，而是蒸馏数据的来源口径。监督信号来自目标模型在图文输入上的自采样分布，因此换目标模型就等于换监督分布，草稿必须重训而不能沿用。若目标模型换了视觉编码器或改变了图像 token 的投影方式，草稿侧的多模态自适应层输入维度与语义都要重对齐；只换语言解码器而视觉侧不变时，可保留自适应层、只重跑自蒸馏。判断标准很直接：草稿消费的视觉条件必须与目标模型验证时使用的视觉表示同源，否则接受率会退化到接近文本域草稿的水平。</p>\n<p>失效条件集中在两处。其一是分布外长尾图文负载：蒸馏数据覆盖不到的问题形态，草稿分布在视觉条件下偏离目标分布，接受前缀变短，目标模型前向次数回升。其二是视觉 token 数量增大：草稿上下文随图像 token 线性变长，轻量前向的单步代价上升，抵消投机收益。可用一个净收益判据约束部署：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{speedup}] \\approx \\frac{c_{\\text{tgt}}}{c_{\\text{draft}}\\cdot k/\\bar{a} + c_{\\text{tgt}}/\\bar{a}},\\quad \\bar{a}=\\frac{\\text{接受 token 数}}{\\text{草稿轮数}}$$</div>\n<p>其中 $\\bar{a}$ 为每轮平均接受长度，$k$ 为草稿步数。$\\bar{a}$ 趋近 1 时草稿开销占比上升，方案退化为无收益的额外前向；$\\bar{a}$ 足够大时目标模型前向被摊薄。工程上应把 $\\bar{a}$ 与每轮目标前向次数作为上线门槛指标，而不是只看离线加速比。</p>\n<table class=\"mini\"><thead><tr><th>迁移场景</th><th>必须改动</th><th>风险点</th></tr></thead><tbody><tr><td>同视觉编码器、换语言解码器</td><td>重跑自蒸馏，保留自适应层</td><td>监督分布漂移</td></tr><tr><td>换视觉编码器或投影</td><td>自适应层输入重对齐</td><td>视觉条件不同源</td></tr><tr><td>高分辨率、长视觉 token</td><td>草稿上下文分桶、限 k</td><td>草稿单步代价上升</td></tr><tr><td>长尾领域图文</td><td>补采蒸馏数据</td><td>接受率下降抵消收益</td></tr></tbody></table>\n<p>规模上限由显存与验证并行度共同决定。草稿可放低精度档位腾出 KV cache 空间，但目标模型对 k 个候选位置做一次并行前向，k 增大会抬高验证阶段的激活与带宽占用；草稿与目标同卡部署时，两者显存叠加压缩可驻留并发数，分离部署则引入跨卡传输延迟。Blackwell 上可用的判断是：先按视觉 token 数分桶测 $\\bar{a}$ 与目标前向次数，再决定 k 与草稿精度档位；若长尾桶的 $\\bar{a}$ 低于阈值，应回退到目标模型单独解码而非强行开启投机。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">MASSV: Multimodal </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Adaptation and Self-D…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · MASSV: Multimodal Adapt… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称</td></tr><tr><td>基线</td><td>材料未给出具体基线名称</td></tr><tr><td>主要结果</td><td>材料未给出接受率、加速比与吞吐数字；论文主张通过自数据蒸馏与多模态自适应提…</td></tr><tr><td>消融</td><td>材料未给出消融实验细节；从机制上看，多模态自适应与自数据蒸馏分别作用于草稿…</td></tr><tr><td>局限</td><td>材料未给出实验规模与硬件档位；方法依赖目标模型生成蒸馏数据，蒸馏数据的覆盖…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-massv-multimodal-adaptation-and-self-2025 · 共 9 个片段</p>\n";break;}}})();
